  --wip-hero-bg: color-mix(in srgb, hsl(from var(--wip-hero-tint) h 55% 48%) 26%, #2a2b30);
  --wip-hero-wash-a: hsl(from var(--wip-hero-tint) h 70% 45% / 0.22);
  --wip-hero-wash-b: hsl(from var(--wip-hero-tint) calc(h + 40) 70% 42% / 0.18);
  --wip-hero-wash-c: hsl(from var(--wip-hero-tint) calc(h - 30) 70% 40% / 0.16);
  --wip-hero-ring: rgb(255 255 255 / 0.07);
  --wip-hero-dot: rgb(255 255 255 / 0.08);
  --wip-hero-art-shadow: 0 18px 34px -18px rgb(0 0 0 / 0.7), 0 0 0 1px var(--wip-card-line);
}
html:root #dev-workshop .dev-ws[data-ws-tab="status"] > .dev-ws-tabbody > .dev-ws-hero-summary {
