  box-shadow: inset 0 0 0 1px var(--wip-hero-line), var(--wip-hero-shadow);
  color: var(--wip-hero-ink);
}
/* THE HERO'S SCENERY, all in one layer behind its words, for show only. It
   is clipped to the card on its own, so the card itself clips nothing (its
   ⋯ menu hangs out of it). Three soft washes of the hue drift slowly round
   each other; a field of dots thins out toward the words; rings spread from
   where the picture is; and the picture floats: the project's own
   illustration, tilted, with its icon in front, or the icon alone. */
html:root #dev-workshop .dev-ws-hero-summary > :is(.wip-hero-art, .wip-hero-wash) { grid-column: auto; grid-row: auto; }
.wip-hero-art {
  position: absolute;
  z-index: -1;
  inset: 0;
  overflow: hidden;
  border-radius: inherit;
  pointer-events: none;
  background-image: radial-gradient(var(--wip-hero-dot) 1px, transparent 1.5px);
  background-size: 20px 20px;
  -webkit-mask-image: var(--wip-hero-dots-mask);
  mask-image: var(--wip-hero-dots-mask);
}
.wip-hero-wash {
  position: absolute;
  z-index: -2;
  inset: 0;
  overflow: hidden;
  border-radius: inherit;
  pointer-events: none;
}
.wip-hero-wash::before {
  content: "";
  position: absolute;
  inset: -40%;
  background-image:
    radial-gradient(closest-side, var(--wip-hero-wash-a), transparent) ,
    radial-gradient(closest-side, var(--wip-hero-wash-b), transparent),
    radial-gradient(closest-side, var(--wip-hero-wash-c), transparent);
  background-size: 52% 62%, 46% 58%, 44% 54%;
  background-position: 8% 20%, 96% 30%, 62% 96%;
  background-repeat: no-repeat;
  filter: blur(40px);
  animation: wip-hero-drift var(--wip-hero-drift) ease-in-out infinite alternate;
}
.wip-hero-rings {
  position: absolute;
  inset-block-start: 50%;
  inset-inline-end: 14%;
  width: 44rem;
  aspect-ratio: 1;
  border-radius: 50%;
  translate: 50% -50%;
  background-image: repeating-radial-gradient(circle, transparent 0 3rem, var(--wip-hero-ring) 3rem calc(3rem + 1px));
  -webkit-mask-image: var(--wip-hero-rings-mask);
  mask-image: var(--wip-hero-rings-mask);
}
.wip-hero-stage {
  position: absolute;
  inset-block: 0;
  inset-inline-end: 0;
  width: min(30%, 20rem);
  display: none;
  place-items: center;
  animation: wip-hero-float var(--wip-hero-float) ease-in-out infinite alternate;
}
.wip-hero-art-pic {
  position: absolute;
  inset-inline-end: 14%;
  width: 44%;
  aspect-ratio: 16 / 10;
  object-fit: cover;
  border-radius: var(--wip-radius-card);
  box-shadow: var(--wip-hero-art-shadow);
  transform: rotate(-5deg) translateY(-4%);
  transition: transform 0.5s cubic-bezier(0.2, 0.8, 0.2, 1);
}
.wip-hero-art-icon {
  position: relative;
  width: var(--wip-hero-art);
  height: var(--wip-hero-art);
  overflow: hidden;
  display: grid;
  place-items: center;
  border-radius: calc(var(--wip-hero-art) * 0.24);
  font-size: calc(var(--wip-hero-art) / 2);
  box-shadow: var(--wip-hero-art-shadow);
  transform: rotate(8deg);
  transition: transform 0.5s cubic-bezier(0.2, 0.8, 0.2, 1);
}
.wip-hero-art-icon > img { width: 100%; height: 100%; object-fit: cover; }
.wip-hero-art-pic + .wip-hero-art-icon { --wip-hero-art: 3.25rem; align-self: end; justify-self: start; margin: 0 0 0.75rem 22%; }
/* The pointer on the card straightens the picture a little, as if picked up. */
html:root .dev-ws-hero-summary:hover .wip-hero-art-pic { transform: rotate(-2deg) translateY(-7%) scale(1.03); }
html:root .dev-ws-hero-summary:hover .wip-hero-art-icon { transform: rotate(3deg) scale(1.05); }
@media (min-width: 900px) {
  .wip-hero-stage { display: grid; }
