  html:root #dev-workshop .dev-ws[data-ws-tab="status"] > .dev-ws-tabbody > .dev-ws-hero-summary { padding-inline-end: calc(min(30%, 20rem) + 1.5rem); }
}
@media (prefers-reduced-motion: reduce) {
  html:root .wip-hero-wash::before { animation: none; }
  html:root .wip-hero-stage { animation: none; }
  html:root .wip-hero-art-pic { transition: none; }
  html:root .wip-hero-art-icon { transition: none; }
}
html:root:where([data-motion="reduce"]) .wip-hero-wash::before { animation: none; }
html:root:where([data-motion="reduce"]) .wip-hero-stage { animation: none; }
html:root:where([data-motion="reduce"]) .wip-hero-art-pic { transition: none; }
