/* It ends the label's row (asked 20 Nov 2026): the label at the start, the link at the end. */
html:root :is(.home-area-label > span:first-child, #home-needs-card-title):has(.wip-fold-pill),
html:root .wip-head-more:has(> .wip-fold-pill) { display: flex; flex: 1 1 auto; }
html:root .wip-head-more > .wip-fold-pill { margin-inline-start: auto; }
@media (hover: hover) { html:root .wip-head-more:hover > .wip-fold-pill { background: transparent; text-decoration-color: currentColor; } }
html:root .wip-head-more:active > .wip-fold-pill { box-shadow: none; transform: none; }
/* END OF HOME. */
/* Its hero's two slow movements (named here, outside the block its guard reads rule by rule). */
@keyframes wip-hero-drift {
  from { transform: rotate(0deg) scale(1); }
  to { transform: rotate(14deg) scale(1.12); }
}
@keyframes wip-menu-rise {
  from { opacity: 0; transform: translateY(-4px) scale(0.98); }
  to { opacity: 1; transform: none; }
}
@keyframes wip-board-link-draw {
  to { stroke-dashoffset: 0; }
}
@keyframes wip-board-link-head {
  to { opacity: 0.75; }
}
@keyframes wip-hero-float {
  from { transform: translateY(-5px); }
  to { transform: translateY(7px); }
}


/* Home's lists (features/home/index.tsx `.home-main`): a flex child that may
   shrink, so a long line is cut and never widens the page. */
.home-main {
  min-width: 0;
}

/* ── A COMMUNITY'S CARD ("New, lighter", approved 20 Nov 2026) ────────────
   frontend/src/features/communities/card.tsx draws it wherever a community
   is a card. The big card: its picture first, edge to edge and 16:9, the
   icon standing mostly below the picture's lower edge on a thin light
   outline, the name over how many members beside it, what it says it is in
   two lines at most, then this week in words at the card's foot. A card
   with no picture draws its icon as the picture, on a wash of the icon's
   colour (THE CARD WITH NO PICTURE, below). The compact card
   (`data-cm-size="compact"`) is the same card with the picture taken off.
   Every value a look may draw its own way is a --cm-*
   token set on <html>: these are the shell's own, and the standard look and
   the brand look each set theirs. */
:root {
  --cm-bg: var(--dc-sheet-solid);
  --cm-radius: 16px;
  /* At rest, under the pointer on a card that opens a place (a hairline a
     step firmer), and under the pointer on one that lifts off the page. */
  --cm-edge: inset 0 0 0 1px var(--app-sheet-line);
  --cm-edge-on: inset 0 0 0 1px var(--border);
  --cm-edge-lift: inset 0 0 0 1px var(--app-sheet-line), 0 2px 4px rgb(0 0 0 / 0.05), 0 22px 36px -14px rgb(0 0 0 / 0.34);
  --cm-ink: var(--text-primary);
  --cm-muted: var(--text-muted);
  --cm-body: var(--text-secondary);
  --cm-link: var(--accent);
  /* The small words: members, what it is, this week. */
  --cm-small: 12px;
  --cm-small-line: 17px;
  /* The grid: the least a card is given, the gap, and the most to a row. */
  --cm-card-min: 264px;
  --cm-gap: 16px;
  --cm-cols: 1;
  /* The icon: the outline round it on a picture, its edge on a white card, and the tile under an emoji. */
  --cm-icon-outline: rgb(255 255 255 / 0.85);
  --cm-icon-edge: rgb(0 0 0 / 0.08);
  --cm-icon-tile: #ffffff;
  /* What a picture stands on while it loads. */
  --cm-pic-ground: rgb(0 0 0 / 0.05);
  /* A card with no picture (23 Nov 2026): its icon in the band, how much of
     the icon's colour the wash takes at the band's middle and at its edges
     (mixed into the card's own ground, so every look's card keeps its
     ground), and the brand tints a card with no colour of its own wears,
     one per community (lib/community-color.ts `bandTint`). */
  --cm-band-icon: 64px;
  --cm-band-icon-radius: 16px;
  --cm-band-icon-shadow: 0 1px 2px rgb(0 0 0 / 0.08), 0 8px 18px -6px rgb(0 0 0 / 0.3);
  --cm-band-tile: #ffffff;
  --cm-band-near: 20%;
  --cm-band-far: 38%;
  --cm-tint-1: #f5c518;
  --cm-tint-2: #4f9be8;
  --cm-tint-3: #8a90f2;
  --cm-tint-4: #3fb68b;
  --cm-tint-5: #f08a5d;
}
@media (min-width: 640px) { :root { --cm-cols: 2; } }
@media (min-width: 1024px) { :root { --cm-cols: 4; } }
.dark {
  --cm-icon-edge: rgb(255 255 255 / 0.14);
  --cm-icon-tile: #2a2a2d;
  --cm-pic-ground: rgb(255 255 255 / 0.08);
  /* In the dark the wash is a breath of the colour and the tints are dimmed
     (a bright yellow band was the loudest thing on the dark page). */
  --cm-band-icon-shadow: 0 1px 2px rgb(0 0 0 / 0.35), 0 8px 18px -6px rgb(0 0 0 / 0.6);
  --cm-band-tile: #2a2a2d;
  --cm-band-near: 18%;
  --cm-band-far: 32%;
  --cm-tint-1: #b89a2e;
  --cm-tint-2: #3f78b8;
  --cm-tint-3: #6b6fc0;
  --cm-tint-4: #2f8a6b;
  --cm-tint-5: #b8674a;
}
/* A row gives each card at least --cm-card-min and holds no more than
   --cm-cols: four where four fit, fewer as it narrows. The cards of a row
   share its height, each with its words at the top; a row is as tall as
   its own tallest card, so one long name does not stretch every row. */
.cm-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(max(var(--cm-card-min), (100% - (var(--cm-cols) - 1) * var(--cm-gap)) / var(--cm-cols)), 1fr));
  gap: var(--cm-gap);
}
/* Joined on a phone: one compact card to a line, close together. */
@media (max-width: 767.98px) {
  .cm-grid[data-cm-grid="joined"] {
    grid-template-columns: minmax(0, 1fr);
    gap: 8px;
  }
}
/* Joined from 768px: two compact cards across, three from 1280px, so each
   has room for its week on one line. */
@media (min-width: 768px) {
  .cm-grid[data-cm-grid="joined"] { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (min-width: 1280px) {
  .cm-grid[data-cm-grid="joined"] { grid-template-columns: repeat(3, minmax(0, 1fr)); }
}
.cm-card {
  position: relative;
  display: flex;
  flex-direction: column;
  min-width: 0;
  overflow: hidden;
  border-radius: var(--cm-radius);
  background-color: var(--cm-bg);
  box-shadow: var(--cm-edge);
  color: var(--cm-ink);
  text-align: start;
  text-decoration: none;
  transition: box-shadow 150ms ease;
}
/* A card that opens a place: its edge a step firmer under the pointer, but
   not while the page is being edited. */
@media (hover: hover) {
  a.cm-card:hover { box-shadow: var(--cm-edge-on); }
  [data-editing] a.cm-card:hover { box-shadow: var(--cm-edge); }
}
.cm-card-pic {
  position: relative;
  display: block;
  flex: none;
  width: 100%;
  aspect-ratio: 16 / 9;
  overflow: hidden;
  background: var(--cm-pic-ground) center / cover no-repeat;
}
/* THE CARD WITH NO PICTURE (decided 23 Nov 2026; phone review #39, #66,
   #134, S10): the band is the icon, large and centred, on a soft wash of its
   main colour (`data-cm-band="wash"`, `--cm-wash` set on the band), or of the
   community's brand tint where the icon has little colour or is an emoji or
   a letter (`data-cm-band="tint"`, `data-cm-tint`). While an icon's colour is
   read the band is the plain ground (`data-cm-band="wait"`). No stock
   background: nothing to load, and no two neighbours alike. */
.cm-card-pic[data-cm-band] {
  display: flex;
  align-items: center;
  justify-content: center;
}
.cm-card-pic[data-cm-tint="1"] { --cm-wash: var(--cm-tint-1); }
.cm-card-pic[data-cm-tint="2"] { --cm-wash: var(--cm-tint-2); }
.cm-card-pic[data-cm-tint="3"] { --cm-wash: var(--cm-tint-3); }
.cm-card-pic[data-cm-tint="4"] { --cm-wash: var(--cm-tint-4); }
.cm-card-pic[data-cm-tint="5"] { --cm-wash: var(--cm-tint-5); }
.cm-card-pic:is([data-cm-band="wash"], [data-cm-band="tint"]) {
  background: radial-gradient(farthest-corner at 50% 45%, color-mix(in oklab, var(--cm-wash) var(--cm-band-near), var(--cm-bg)), color-mix(in oklab, var(--cm-wash) var(--cm-band-far), var(--cm-bg)));
}
/* The band's icon and what is drawn on it (the votes waiting, the edit discs). */
.cm-band-face {
  position: relative;
  z-index: 1;
  display: inline-flex;
}
.cm-band-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: var(--cm-band-icon);
  height: var(--cm-band-icon);
  overflow: hidden;
  border-radius: var(--cm-band-icon-radius);
  box-shadow: var(--cm-band-icon-shadow);
  font-size: 34px;
  font-weight: 700;
  line-height: 1;
  color: var(--cm-muted);
}
/* An emoji or an initial: the glyph large on a white tile. */
.cm-band-icon:not([data-icon="image"]) { background-color: var(--cm-band-tile); }
.cm-band-icon > img {
  display: block;
  width: 100%;
  height: 100%;
  border-radius: 0;
  object-fit: cover;
}
.cm-band-icon > span:not(.app-icon-wait) { font-size: inherit; }
.cm-card-img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
}
.cm-card-body {
  display: flex;
  flex: 1 1 auto;
  flex-direction: column;
  min-width: 0;
  padding: 0 12px 14px;
}
.cm-card-head {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  min-width: 0;
}
/* The icon and what is drawn on it (the votes waiting, the edit discs). It
   rises 14px over the picture's lower edge and stands above it. */
.cm-card-face {
  position: relative;
  z-index: 1;
  display: inline-flex;
  flex: none;
  margin-top: -14px;
}
.cm-card-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 56px;
  height: 56px;
  overflow: hidden;
  border-radius: 14px;
  box-shadow: 0 0 0 1.5px var(--cm-icon-outline);
  font-size: 30px;
  font-weight: 700;
  line-height: 1;
  color: var(--cm-muted);
}
/* No ground under a picture: an emoji or an initial is on a white tile. */
.cm-card-icon:not([data-icon="image"]) { background-color: var(--cm-icon-tile); }
.cm-card-icon > img {
  display: block;
  width: 100%;
  height: 100%;
  border-radius: 0;
  object-fit: cover;
}
.cm-card-icon > span:not(.app-icon-wait) { font-size: inherit; }
.cm-card-id {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
  padding-top: 6px;
}
/* Nothing beside the name: it starts at the card's left edge, a little
   under the band. */
.cm-card-body[data-cm-bare] .cm-card-id { padding-top: 10px; }
.cm-card-name {
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  line-clamp: 2;
  overflow: hidden;
  overflow-wrap: anywhere;
  font-size: 15px;
  font-weight: 650;
  line-height: 1.25;
  color: var(--cm-ink);
}
.cm-card-members {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: var(--cm-small);
  line-height: var(--cm-small-line);
  font-variant-numeric: tabular-nums;
  color: var(--cm-muted);
}
.cm-card-desc {
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  line-clamp: 2;
  overflow: hidden;
  overflow-wrap: anywhere;
  margin-top: 9px;
  font-size: var(--cm-small);
  line-height: var(--cm-small-line);
  color: var(--cm-body);
}
/* This week, at the card's foot, at least 12px under the words, so every
   card of a row has it on one line (phone review S3: it sat under the name
   on one card and at the foot of its neighbour). The dot between its two
   parts is drawn before each, in the 14px before it; the line starts 14px
   early and its box cuts that off, so a line (the first, or one that wraps)
   never starts with a dot. */
.cm-card-week {
  display: block;
  overflow: hidden;
  margin-top: auto;
  padding-top: 12px;
  font-size: var(--cm-small);
  line-height: var(--cm-small-line);
  font-variant-numeric: tabular-nums;
  color: var(--cm-body);
}
.cm-week-in {
  display: flex;
  flex-wrap: wrap;
  margin-inline-start: -14px;
}
.cm-week-in > span {
  position: relative;
  padding-inline-start: 14px;
}
.cm-week-in > span::before {
  content: "\00B7";
  content: "\00B7" / "";
  position: absolute;
  inset-inline-start: 5px;
  font-weight: 400;
  color: var(--cm-muted);
}
.cm-week-live {
  font-weight: 600;
  color: var(--cm-link);
}
/* FEATURED'S FIRST ROW, LARGER (asked 20 Nov 2026), signed in or out:
   features/communities/card.tsx `useLeadCount` decides how many (one fewer
   than a row of the rest, three at most; the whole width on a phone) and
   sets --cm-lead-cols; the rest of Featured is the grid under it. */
.cm-grid[data-cm-grid="lead"] { grid-template-columns: repeat(var(--cm-lead-cols, 3), minmax(0, 1fr)); }
.cm-grid[data-cm-grid="lead"] + .cm-grid { margin-top: var(--cm-gap); }
/* A lone featured card across a row meant for two or three
   (features/home/communities-to-join.tsx `lone`): its picture is a band, not
   16:9 across the whole page. */
.cm-grid[data-cm-grid="lead"][data-cm-lone] .cm-card-pic { aspect-ratio: 3 / 1; max-height: 15rem; }
.cm-card[data-cm-size="lead"] .cm-card-body { padding: 0 16px 18px; }
.cm-card[data-cm-size="lead"] .cm-card-head { gap: 14px; }
.cm-card[data-cm-size="lead"] .cm-card-face { margin-top: -18px; }
.cm-card[data-cm-size="lead"] .cm-card-icon {
  width: 68px;
  height: 68px;
  border-radius: 17px;
  font-size: 36px;
}
.cm-card[data-cm-size="lead"] .cm-card-id { padding-top: 8px; }
.cm-card[data-cm-size="lead"] .cm-card-name { font-size: 18px; line-height: 22px; }
.cm-card[data-cm-size="lead"] :is(.cm-card-members, .cm-card-desc, .cm-card-week) { font-size: 14px; line-height: 20px; }
.cm-card[data-cm-size="lead"] .cm-card-desc { margin-top: 10px; }
.cm-card[data-cm-size="lead"] .cm-band-icon {
  --cm-band-icon: 80px;
  --cm-band-icon-radius: 20px;
  font-size: 42px;
}
.cm-card[data-cm-size="lead"] .cm-card-body[data-cm-bare] .cm-card-id { padding-top: 14px; }
/* A PHONE (under 640px): two cards to a row, 12px apart, each a size down
   (the icon 44px, 11px over the picture's edge, the name 14px); Featured's
   first card the whole width, its icon 60px. */
@media (max-width: 639.98px) {
  .cm-grid:is([data-cm-grid="join"], [data-cm-grid="lead"]) { gap: 12px; }
  .cm-grid[data-cm-grid="lead"] + .cm-grid { margin-top: 12px; }
  .cm-grid[data-cm-grid="join"] { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .cm-grid[data-cm-grid="join"] .cm-card-body { padding: 0 10px 12px; }
  .cm-grid[data-cm-grid="join"] .cm-card-head { gap: 9px; }
  .cm-grid[data-cm-grid="join"] .cm-card-face { margin-top: -11px; }
  .cm-grid[data-cm-grid="join"] .cm-card-icon {
    width: 44px;
    height: 44px;
    border-radius: 11px;
    font-size: 24px;
  }
  .cm-grid[data-cm-grid="join"] .cm-card-id { gap: 1px; padding-top: 5px; }
  .cm-grid[data-cm-grid="join"] .cm-card-body[data-cm-bare] .cm-card-id { padding-top: 9px; }
  .cm-grid[data-cm-grid="join"] .cm-card-name { font-size: 14px; line-height: 17px; }
  .cm-card[data-cm-size="lead"] .cm-card-face { margin-top: -15px; }
  .cm-card[data-cm-size="lead"] .cm-card-icon {
    width: 60px;
    height: 60px;
    border-radius: 15px;
  }
  .cm-card[data-cm-size="lead"] .cm-card-name { font-size: 17px; line-height: 21px; }
}
/* A card that lifts off the page under the pointer (Discover's: the card
   rises by its own classes, ../guest/guest-discover.tsx), onto a shadow,
   its picture growing a little; still for anyone who asks for less motion. */
@media (hover: hover) {
  .cm-card[data-cm-lift]:hover { box-shadow: var(--cm-edge-lift); }
  .cm-card[data-cm-lift] :is(.cm-card-img, .cm-band-face) { transition: transform 300ms ease-out; }
  .cm-card[data-cm-lift]:hover :is(.cm-card-img, .cm-band-face) { transform: scale(1.04); }
}
@media (prefers-reduced-motion: reduce) {
  .cm-card[data-cm-lift] :is(.cm-card-img, .cm-band-face) { transition: none; }
  .cm-card[data-cm-lift]:hover :is(.cm-card-img, .cm-band-face) { transform: none; }
}
:where(html[data-motion="reduce"]) .cm-card[data-cm-lift] :is(.cm-card-img, .cm-band-face) { transition: none; }
:where(html[data-motion="reduce"]) .cm-card[data-cm-lift]:hover :is(.cm-card-img, .cm-band-face) { transform: none; }
/* A card held in place while the list is read: the card's ground, its
   picture's shape, and about as tall as a card's words. */
.cm-card-skel .cm-card-pic { background-color: var(--cm-pic-ground); }
.cm-card-skel-body { display: block; height: 130px; }
.cm-card-skel[data-cm-size="lead"] .cm-card-skel-body { height: 150px; }
@media (max-width: 639.98px) {
  .cm-grid[data-cm-grid="join"] .cm-card-skel-body { height: 110px; }
}
/* The compact card: the icon smaller, on a dark hairline (it sits on the
   card's own white), beside the name and its week, centred, with room round
   them: 16px in, 14px from the icon to the words, 5px between the lines,
   the small words 13px on 18px. */
.cm-card[data-cm-size="compact"] { padding: 16px; }
.cm-card[data-cm-size="compact"] .cm-card-head { align-items: center; gap: 14px; }
.cm-card[data-cm-size="compact"] .cm-card-face { margin-top: 0; }
.cm-card[data-cm-size="compact"] .cm-card-icon {
  width: 44px;
  height: 44px;
  border-radius: 11px;
  box-shadow: 0 0 0 1px var(--cm-icon-edge);
  font-size: 24px;
}
.cm-card[data-cm-size="compact"] .cm-card-id { gap: 5px; padding-top: 0; }
.cm-card[data-cm-size="compact"] :is(.cm-card-members, .cm-card-live) { font-size: 13px; line-height: 18px; }
/* Its first line ("34 members, 6 active this week") wraps between its two
   facts, never inside one; a fact longer than the card ends in an ellipsis. */
.cm-card[data-cm-size="compact"] .cm-card-members { white-space: normal; }
.cm-card-fact {
  display: inline-block;
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  vertical-align: top;
}
/* What went live this week, under it: a tick and the words in the link's
   blue, the one coloured thing on the card. */
.cm-card-live {
  display: flex;
  align-items: center;
  gap: 5px;
  min-width: 0;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  color: var(--cm-link);
}
.cm-card-live-tick {
  flex: none;
  width: 14px;
  height: 14px;
}

/* ── ONE LOOK · THE COMMUNITY CARD AS A COVER AND A ROW (design review, 25 Nov
   2026; the area "HOME, COMMUNITIES, YOU, SETTINGS AND CHALLENGES" at the foot
   of this file). In the standard look, on Home and the Communities page:
   Featured and a pinned community are covers (the colour band with the icon
   in its middle, then the name and one line), and on a phone the joined
   communities are rows of one list card. Here, in the card's own block,
   because only this block names the card's parts. ── */
/* A cover: the community's colour band with its icon in the middle, then its
   name and one line. Featured is one grid of them, two across on a phone and
   three on a desktop (features/home/communities-to-join.tsx draws every
   featured community in it). */
html:root :is(#home-screen, #communities-screen) [data-home-join-featured] .cm-grid[data-cm-grid="lead"],
html:root #communities-screen .cm-grid[data-cm-grid="pinned"] {
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}
@media (min-width: 768px) {
  html:root :is(#home-screen, #communities-screen) [data-home-join-featured] .cm-grid[data-cm-grid="lead"] { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 12px; }
  html:root #communities-screen .cm-grid[data-cm-grid="pinned"] { gap: 20px; }
}
html:root :is(#home-screen, #communities-screen) :is([data-home-join-featured] .cm-grid[data-cm-grid="lead"], .cm-grid[data-cm-grid="pinned"]) {
  --cm-band-icon: 44px;
  --cm-band-icon-radius: 12px;
  --cm-band-icon-shadow: 0 8px 16px -10px rgb(18 26 14 / 0.45);
}
html:root :is(#home-screen, #communities-screen) :is([data-home-join-featured] .cm-grid, .cm-grid[data-cm-grid="pinned"]) .cm-card .cm-card-pic {
  height: 76px;
  max-height: none;
  aspect-ratio: auto;
}
html:root :is(#home-screen, #communities-screen) :is([data-home-join-featured] .cm-grid, .cm-grid[data-cm-grid="pinned"]) .cm-card .cm-band-icon {
  --cm-band-icon: 44px;
  --cm-band-icon-radius: 12px;
  font-size: 22px;
}
/* A community's icon is drawn in the opaque ink: an emoji takes the alpha of
   its words' colour, and the muted ink (60%) left every emoji on a card pale. */
html:root :is(#home-screen, #communities-screen) .cm-card :is(.cm-band-icon, .cm-card-icon) { color: var(--one-ink-2); }
html:root :is(#home-screen, #communities-screen) .cm-card :is(.cm-band-icon, .cm-card-icon) > span { color: var(--one-ink); }
html:root :is(#home-screen, #communities-screen) :is([data-home-join-featured] .cm-grid, .cm-grid[data-cm-grid="pinned"]) .cm-card .cm-card-body { gap: 3px; padding: 10px 12px 12px; }
html:root :is(#home-screen, #communities-screen) :is([data-home-join-featured] .cm-grid, .cm-grid[data-cm-grid="pinned"]) .cm-card .cm-card-head { gap: 10px; }
html:root :is(#home-screen, #communities-screen) :is([data-home-join-featured] .cm-grid, .cm-grid[data-cm-grid="pinned"]) .cm-card .cm-card-id { flex: 1 1 auto; gap: 3px; padding-top: 0; }
html:root :is(#home-screen, #communities-screen) :is([data-home-join-featured] .cm-grid, .cm-grid[data-cm-grid="pinned"]) .cm-card .cm-card-face { margin-top: -20px; }
html:root :is(#home-screen, #communities-screen) :is([data-home-join-featured] .cm-grid, .cm-grid[data-cm-grid="pinned"]) .cm-card .cm-card-icon { width: 40px; height: 40px; border-radius: 11px; font-size: 20px; }
html:root :is(#home-screen, #communities-screen) :is([data-home-join-featured] .cm-grid, .cm-grid[data-cm-grid="pinned"]) .cm-card .cm-card-name {
