html:root :is(#home-screen, #communities-screen) [data-home-join-featured] .cm-card :is(.cm-card-desc, .cm-card-week) { display: none; }
/* A pin's name with the votes waiting on you beside it, a tag. */
html:root #communities-screen .cm-card-name-row { display: flex; align-items: center; justify-content: space-between; gap: 6px; min-width: 0; }
