@media (min-width: 768px) {
  html:root :is(#home-screen, #communities-screen) :is([data-home-join-featured] .cm-grid, .cm-grid[data-cm-grid="pinned"]) .cm-card .cm-card-pic { height: 96px; }
  html:root #communities-screen .cm-grid[data-cm-grid="pinned"] .cm-card .cm-card-desc { margin-top: 4px; color: var(--one-ink); font-size: 13px; line-height: 18px; -webkit-line-clamp: 1; line-clamp: 1; }
  html:root #communities-screen .cm-grid[data-cm-grid="pinned"] .cm-card .cm-card-week { padding-top: 2px; color: var(--one-ink-2); font-size: 13px; line-height: 18px; }
  html:root #communities-screen .cm-grid[data-cm-grid="pinned"] .cm-card .cm-week-live { color: inherit; font-weight: 400; }
