html:root.dark #communities-screen .cm-grid[data-cm-grid="joined"] .cm-card-icon { background-color: var(--wip-icon-tile); }
html:root #communities-screen .cm-grid[data-cm-grid="joined"] .cm-card-id { gap: 2px; padding-top: 0; }
html:root #communities-screen .cm-grid[data-cm-grid="joined"] .cm-card-name { color: var(--one-ink); font: var(--one-row-title); -webkit-line-clamp: 1; line-clamp: 1; }
html:root #communities-screen .cm-grid[data-cm-grid="joined"] :is(.cm-card-members, .cm-card-live) { color: var(--one-ink-2); font: var(--one-row-sub); }
@media (max-width: 767.98px) {
