  html:root #communities-screen .cm-grid[data-cm-grid="joined"] > .cm-card { padding: 12px 14px; }
  /* There a card is one row: its name over one line of facts, what went live after a dot. */
  html:root #communities-screen .cm-grid[data-cm-grid="joined"] .cm-card-id { display: block; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; color: var(--one-ink-2); font: var(--one-row-sub); }
  html:root #communities-screen .cm-grid[data-cm-grid="joined"] .cm-card-name { display: block; margin-bottom: 2px; overflow: hidden; text-overflow: ellipsis; }
