.shots-viewer:has(.shots-side-both:checked) .shots-stage > .shots-flip-side { width: min(calc(50cqw - 6px), calc(100cqh * (var(--shots-shape, 16 / 10)))); }
.shots-viewer:has(.shots-side-both:checked) .shots-stage > .shots-flip-after { grid-area: 1 / 2; }
.shots-viewer:has(.shots-side-both:checked) .shots-flip-to { display: none; }
.shots-viewer:has(.shots-side-both:checked) .shots-flip-chip-after { inset-inline-start: calc(50% + 16px); }
.shots-viewer:has(.shots-side-both:checked) .shots-stage::after { content: ""; position: absolute; top: 12px; bottom: 12px; left: 50%; width: 1px; background: rgba(24, 24, 27, 0.12); }
.dark .shots-viewer:has(.shots-side-both:checked) .shots-stage::after { background: rgba(255, 255, 255, 0.14); }
.shots-viewer:has(.shots-side-both:checked) .shots-seg-both,
.shots-viewer:has(.shots-zoom-close:checked) .shots-seg-close,
.shots-viewer:has(.shots-zoom-whole:checked) .shots-seg-whole { background: #fff; color: #1c1c1e; box-shadow: 0 1px 2px rgba(0, 0, 0, 0.14); }
.dark .shots-viewer:has(.shots-side-both:checked) .shots-seg-both,
.dark .shots-viewer:has(.shots-zoom-close:checked) .shots-seg-close,
.dark .shots-viewer:has(.shots-zoom-whole:checked) .shots-seg-whole { background: #3a3a3c; color: #f5f5f7; }
.shots-viewer:has(.shots-side-both:checked) .shots-change-n { background: linear-gradient(90deg, #dc2626 50%, #16a34a 50%); }
.shots-viewer:has(.shots-zoom-pick:focus-visible) .shots-seg-zoom { outline: 2px solid var(--accent, #2563eb); outline-offset: 2px; }
.shots-viewer:has(.shots-zoom-whole:checked) .shots-close-only,
.shots-viewer:has(.shots-zoom-close:checked) .shots-whole-only { display: none; }
/* Auto, with no room: After. */
@container (max-width: 419.98px) {
  .shots-viewer:has(.shots-side-auto:checked) .shots-view[data-shots-viewport="phone"] .shots-flip-before { visibility: hidden; }
  .shots-viewer:has(.shots-side-auto:checked) .shots-view[data-shots-viewport="phone"] .shots-flip-chip-before,
  .shots-viewer:has(.shots-side-auto:checked) .shots-view[data-shots-viewport="phone"] .shots-flip-to-after { display: none; }
