  .shots-viewer:has(.shots-side-auto:checked) .shots-view[data-shots-viewport="desktop"] .shots-flip-chip-before,
  .shots-viewer:has(.shots-side-auto:checked) .shots-view[data-shots-viewport="desktop"] .shots-flip-to-after { display: none; }
  .shots-viewer:has(.shots-side-auto:checked) .shots-view[data-shots-viewport="desktop"] .shots-seg-after { color: #fff; background: #15803d; box-shadow: 0 1px 2px rgba(0, 0, 0, 0.14); }
}
/* Auto, with room: side by side. */
@container (min-width: 420px) {
  .shots-viewer:has(.shots-side-auto:checked) .shots-view[data-shots-viewport="phone"] .shots-stage { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); column-gap: 12px; }
  .shots-viewer:has(.shots-side-auto:checked) .shots-view[data-shots-viewport="phone"] .shots-stage > .shots-flip-side { width: min(calc(50cqw - 6px), calc(100cqh * (var(--shots-shape, 16 / 10)))); }
