  .shots-viewer:has(.shots-side-auto:checked) .shots-view[data-shots-viewport="phone"] .shots-flip-chip-after { inset-inline-start: calc(50% + 16px); }
  .shots-viewer:has(.shots-side-auto:checked) .shots-view[data-shots-viewport="phone"] .shots-change-n { background: linear-gradient(90deg, #dc2626 50%, #16a34a 50%); }
  .shots-viewer:has(.shots-side-auto:checked) .shots-view[data-shots-viewport="phone"] .shots-seg-both { background: #fff; color: #1c1c1e; box-shadow: 0 1px 2px rgba(0, 0, 0, 0.14); }
