  .shots-viewer:has(.shots-side-auto:checked) .shots-view[data-shots-viewport="phone"] .shots-stage[data-shots-stack]::after { top: 50%; bottom: auto; inset-inline-start: 12px; inset-inline-end: 12px; width: auto; }
}
@container (min-width: 720px) {
  .shots-viewer:has(.shots-side-auto:checked) .shots-view[data-shots-viewport="desktop"] .shots-stage { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); column-gap: 12px; }
  .shots-viewer:has(.shots-side-auto:checked) .shots-view[data-shots-viewport="desktop"] .shots-stage > .shots-flip-side { width: min(calc(50cqw - 6px), calc(100cqh * (var(--shots-shape, 16 / 10)))); }
