  .shots-viewer:has(.shots-side-auto:checked) .shots-view[data-shots-viewport="desktop"] .shots-flip-to { display: none; }
  .shots-viewer:has(.shots-side-auto:checked) .shots-view[data-shots-viewport="desktop"] .shots-flip-chip-after { inset-inline-start: calc(50% + 16px); }
  .shots-viewer:has(.shots-side-auto:checked) .shots-view[data-shots-viewport="desktop"] .shots-change-n { background: linear-gradient(90deg, #dc2626 50%, #16a34a 50%); }
  .shots-viewer:has(.shots-side-auto:checked) .shots-view[data-shots-viewport="desktop"] .shots-seg-both { background: #fff; color: #1c1c1e; box-shadow: 0 1px 2px rgba(0, 0, 0, 0.14); }
  .dark .shots-viewer:has(.shots-side-auto:checked) .shots-view[data-shots-viewport="desktop"] .shots-seg-both { background: #3a3a3c; color: #f5f5f7; }
  /* #5063: the change page's crop and stacked layout, as side by side has. */
  .shots-viewer:has(.shots-side-auto:checked) .shots-view[data-shots-viewport="desktop"] .shots-stage > .shots-flip-side[data-shots-crop] { overflow: hidden; aspect-ratio: var(--shots-crop-shape, 16 / 10); width: min(calc(50cqw - 6px), calc(100cqh * (var(--shots-crop-shape, 16 / 10)))); }
  /* direction: physical: a crop is a box on a PICTURE; --shots-crop-x is a
     percentage of the shot itself, so it stays where it was drawn in Arabic. */
  .shots-viewer:has(.shots-side-auto:checked) .shots-view[data-shots-viewport="desktop"] .shots-flip-side[data-shots-crop] > .shots-crop { inset: auto; left: var(--shots-crop-x, 0); top: var(--shots-crop-y, 0); width: var(--shots-crop-w, 100%); height: auto; aspect-ratio: var(--shots-shape, 16 / 10); }
  /* direction: logical */
  .shots-viewer:has(.shots-side-auto:checked) .shots-view[data-shots-viewport="desktop"] .shots-stage[data-shots-stack] { grid-template-columns: minmax(0, 1fr); grid-template-rows: minmax(0, 1fr) minmax(0, 1fr); column-gap: 0; row-gap: 12px; }
  .shots-viewer:has(.shots-side-auto:checked) .shots-view[data-shots-viewport="desktop"] .shots-stage[data-shots-stack] > .shots-flip-side { overflow: hidden; aspect-ratio: var(--shots-crop-shape, 16 / 10); width: min(100cqw, calc((50cqh - 6px) * (var(--shots-crop-shape, 16 / 10)))); }
  .shots-viewer:has(.shots-side-auto:checked) .shots-view[data-shots-viewport="desktop"] .shots-stage[data-shots-stack] > .shots-flip-after { grid-area: 2 / 1; }
  .shots-viewer:has(.shots-side-auto:checked) .shots-view[data-shots-viewport="desktop"] .shots-stage[data-shots-stack] .shots-flip-chip-after { inset-inline-start: 10px; top: calc(50% + 16px); }
  .shots-viewer:has(.shots-side-auto:checked) .shots-view[data-shots-viewport="desktop"] .shots-stage[data-shots-stack]::after { top: 50%; bottom: auto; inset-inline-start: 12px; inset-inline-end: 12px; width: auto; }
}
/* The spec's toolbar has a third switch, so its labels give way sooner. */
@container (max-width: 560px) {
  .shots-viewer-spec .shots-seg-label { display: none; }
  .shots-viewer-spec .shots-seg-btn { padding: 0 9px; }
}
/* The prose around the screens: diagrams and tables written into an HTML
   spec. A diagram is inline SVG drawn with these few classes, so it follows
   light and dark mode; a literal fill still works, in one theme. */
.spec-html figure { margin: 12px 0; }
.spec-html figure > svg { display: block; width: 100%; max-width: 100%; height: auto; }
.spec-html figcaption { margin-top: 4px; font-size: 12px; color: var(--text-muted, #68686c); }
.spec-html .spec-diagram-wrap { overflow-x: auto; border: 1px solid var(--border-light, #e3e3e6); border-radius: 10px; padding: 10px; background: var(--bg-secondary, #f5f5f7); }
.spec-html svg text { font-family: inherit; fill: var(--text-primary, #0a0a0a); }
.spec-html svg .spec-muted { fill: var(--text-muted, #68686c); }
.spec-html svg .spec-box { fill: var(--bg-primary, #fff); stroke: var(--border, #d1d1d6); stroke-width: 1; }
.spec-html svg .spec-box-changed { fill: var(--bg-primary, #fff); stroke: var(--accent, #0a6ee0); stroke-width: 1.5; }
.spec-html svg .spec-box-new { fill: var(--accent-tint, rgba(10, 110, 224, 0.08)); stroke: var(--accent, #0a6ee0); stroke-width: 1.5; stroke-dasharray: 4 3; }
.spec-html svg .spec-line { fill: none; stroke: var(--text-faint, #8e8e93); stroke-width: 1.2; }
.spec-html svg .spec-arrow { fill: var(--text-faint, #8e8e93); }
.spec-html svg .spec-accent { fill: var(--accent, #0a6ee0); }
.spec-html svg .spec-good { fill: #16a34a; }
.spec-html svg .spec-bad { fill: #dc2626; }
/* A plan's own pictures: screenshots uploaded to Homeroom, shown in the
   text (frontend/src/lib/spec-html.ts keeps only those). A `spec-strip` is
   a row of captioned pictures that scrolls sideways, the way a design doc
   lays out a flow of phone screens. */
.spec-html img { display: block; max-width: 100%; height: auto; border-radius: 12px; }
.spec-html .spec-strip { display: flex; gap: 16px; overflow-x: auto; scroll-snap-type: x proximity; overscroll-behavior-x: contain; margin: 12px 0; padding: 2px 2px 10px; }
.spec-html .spec-strip > figure { flex: 0 0 auto; width: min(240px, 72%); margin: 0; scroll-snap-align: start; }
.spec-html .spec-strip > figure > img { width: 100%; }
.spec-html .spec-strip figcaption { margin-top: 8px; font-size: 13px; line-height: 1.4; }
.spec-html .spec-screens { margin: 12px 0; }
.spec-html .spec-screens-caption { margin-top: 6px; font-size: 12px; color: var(--text-muted, #68686c); }
.dev-topic-details { margin-top: 8px; }
.dev-topic-details-summary {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  cursor: pointer;
  list-style: none;
  font-size: 12.5px;
  font-weight: 600;
  color: var(--accent);
  user-select: none;
}
.dev-topic-details-summary::-webkit-details-marker { display: none; }
.dev-topic-details-summary::before { content: "▸"; font-size: 11px; }
.dev-topic-details[open] > .dev-topic-details-summary::before { content: "▾"; }
.dev-topic-details-body {
  margin-top: 8px;
  padding: 10px 12px;
  border-radius: 14px;
  background: var(--bg-primary);
  font-size: 13px;
  line-height: 1.5;
  color: var(--text-primary);
}
.dev-topic-note { font-size: 13px; line-height: 1.5; color: var(--text-muted); }
.dev-topic-about-body + .dev-topic-note { margin-top: 8px; }
/* #2603: a governance proposal's vote roster, under the About sheet's
   words. The ledger's review line rendered outside the ledger, so it takes
   the note's size and its own top margin rather than the row grid's. */
.dev-topic-roster { margin-top: 10px; font-size: 13px; line-height: 1.5; }

/* ── Discussion ──
   The app's own thread — `#gc-thread-messages`, the group chat's transcript
   host — is dressed as the sheet after the head. A request's page is its own
   layout (#4453, `.dev-request` below): its GitHub comments are rows of that
   thread. */
#gc-thread-head { display: block; }

/* ── The change page as the Workshop's Needs-you item ──────────────────
   topic/topic-head.tsx ChangeHero, StepsSheet and DetailsSheet. The hero
   borrows the item's pieces by class — the eyebrow, the title, the by-line
   and its avatar, the chips — and adds only what a page needs that a swipe
   card does not: no fixed height and no snap, the title unclamped, the
   chips under the by-line rather than beside it, and the card's action
   band under them. */
.dev-topic-hero {
  position: relative;
  padding: 16px 20px 18px;
  overflow: hidden;
}
.dev-topic-hero[data-ws-tint="a"] { background-image: linear-gradient(165deg, rgba(139, 92, 246, .10), rgba(255, 255, 255, 0) 55%, rgba(244, 114, 182, .08)); }
.dev-topic-hero[data-ws-tint="b"] { background-image: linear-gradient(165deg, rgba(59, 130, 246, .10), rgba(255, 255, 255, 0) 55%, rgba(251, 191, 36, .08)); }
.dark .dev-topic-hero[data-ws-tint="a"] { background-image: linear-gradient(165deg, rgba(139, 92, 246, .16), rgba(0, 0, 0, 0) 55%, rgba(244, 114, 182, .10)); }
.dark .dev-topic-hero[data-ws-tint="b"] { background-image: linear-gradient(165deg, rgba(59, 130, 246, .16), rgba(0, 0, 0, 0) 55%, rgba(251, 191, 36, .08)); }
.dev-topic-hero-top { display: flex; align-items: center; justify-content: space-between; gap: 12px; min-height: 20px; }
.dev-topic-hero-eyebrow { display: inline-flex; align-items: center; gap: 4px; min-width: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.dev-topic-hero-eyebrow > a { color: var(--accent); text-decoration: none; letter-spacing: 0; text-transform: none; font-weight: 700; }
.dev-topic-hero-eyebrow > a:hover { text-decoration: underline; }
/* The item's title, unclamped and at page size: a page has room for the
   whole line, where the swipe card's three-line clamp hid the end of a
   long one behind an ellipsis nobody could open. */
.dev-topic-hero > .dev-topic-hero-title {
  margin: 10px 0 0; max-width: none; display: block; -webkit-line-clamp: unset; overflow: visible;
  font-size: 24px; line-height: 1.2; overflow-wrap: anywhere;
}
.dev-topic-hero > .dev-topic-hero-by { margin-top: 10px; max-width: none; }
/* The card's tags in the Needs-you chip's shape. Each keeps the tint and
   ink utilities it arrived with — the card's own colours — and those
   outrank the chip's neutral fill because tailwind.css loads last. (The
   selectors here are two classes deep on purpose: the item's own rules,
   and its wide-layout ones further down, are one class, and the hero's
   must win whichever comes later in the file.) */
.dev-topic-hero > .dev-topic-hero-chips { margin-top: 10px; flex: none; justify-content: flex-start; }
.dev-topic-hero-chips > .dev-badge { height: 24px; padding: 0 9px; gap: 6px; border-radius: 9999px; font-size: 12px; font-weight: 600; }
.dev-topic-hero-chips > .dev-badge.font-mono { font-size: 11.5px; }
.dev-topic-hero-chips > .dev-badge .attr-avatar { width: 16px; height: 16px; font-size: 0.65rem; }
/* The band wears the card's class for the band rules above — the one-line
   fold into ⋯, the accent pills, Preview and the hamburger at the right;
   the card's own box (its radius, padding and edge) comes off here. */
.dev-topic-hero > div.dev-topic-hero-actions.dev-card-topic {
  margin-top: 12px; padding: 0; border-radius: 0; box-shadow: none; background: none; --dev-edge-w: 0px;
}
/* QA 2026-09-24 Q26: THE HERO'S BAND IS AS TALL AS ITS VOTE BUTTON. The band
   reserves and clips one 28px row (the card rule above), which is right for
   the 28px pills, but the hero also carries the Vote button, and that is
   30px (`.dev-vote-btn`). So the row was 30px inside a 28px window: the Vote
   pill lost its bottom 2px and the round menu button its last pixel, and on
   a phone both read as cut flat along the bottom. 30px here fits the tallest
   thing the hero's band holds; a wrapped second row still starts at 36px
   (30 plus the 6px row gap) and stays clipped, and useFoldedActions' "off the
   row" test reads the band's own height, so the fold is unchanged. Only the
   hero: on a card the Vote button sits in the status row, not in this band. */
.dev-topic-hero .gc-card-actions { margin-top: 0; min-height: 30px; max-height: 30px; }
.dev-topic-hero .gc-card-actions > .dev-vote-btn { margin-inline-end: 4px; }
/* The summary at the item's reading size, the whole of it. */
.dev-topic-hero-summary { margin: 14px 0 0; font-size: 17px; line-height: 1.45; color: var(--text-secondary); }
.dev-topic-hero-summary > :first-child { margin-top: 0; }
.dev-topic-hero-summary > :last-child { margin-bottom: 0; }
/* "Addresses", then the issue as a chip: the number bold, the title after
   it, ellipsised rather than wrapped; the owner's pencil at the line's end. */
.dev-topic-hero-issues { margin-top: 12px; min-width: 0; }
.dev-topic-hero-issues-line { display: flex; flex-wrap: wrap; align-items: center; gap: 6px 8px; font-size: 13px; color: var(--text-muted); }
.dev-topic-hero-issues-k { font-weight: 600; }
.dev-topic-issue { max-width: 100%; height: auto; min-height: 24px; padding-block: 2px 2px; padding-inline: 8px 10px; gap: 6px; text-decoration: none; }
.dev-topic-issue:hover { text-decoration: none; filter: brightness(.96); }
.dev-topic-issue > b { font-weight: 700; flex: none; }
.dev-topic-issue > span { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-weight: 500; }
.dev-topic-hero-issues-edit { margin-inline-start: auto; }
.dev-topic-hero-issues form { margin-top: 4px; }
/* The picture, or the line that says it is coming. */
.dev-topic-hero .dev-topic-visuals { margin-top: 14px; }
.dev-topic-hero .dev-topic-shots { margin-top: 12px; }
.dev-topic-hero-shots { display: inline-flex; align-items: center; gap: 8px; margin: 14px 0 0; font-size: 13px; color: var(--text-muted); }
.dev-topic-hero-shots > .dc-status-spinner-arc { flex: none; margin: 0; }
.dev-topic-hero > .dev-topic-note { margin-top: 12px; }

/* ── The steps: the card's grey strip, expanded ──
   The same panel as card/dev-card.tsx RequirementsRow — its tints ride in
   as the same utilities — with room to say, under each gate, what the
   ledger row for it said. */
.dev-topic-steps { padding: 8px; }
.dev-steps { overflow: hidden; }
.dev-steps-head { display: flex; align-items: baseline; gap: 6px; padding: 10px 14px; font-size: 13px; line-height: 1.35; color: var(--text-secondary); }
.dev-steps-headline { font-weight: 700; color: var(--text-primary); white-space: nowrap; }
.dev-steps-detail { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: var(--text-muted); }
.dev-steps-count { margin-inline-start: auto; font-variant-numeric: tabular-nums; font-size: 12px; color: var(--text-muted); white-space: nowrap; }
.dev-steps-list { list-style: none; margin: 0; padding: 4px 0; }
.dev-step { display: grid; grid-template-columns: 22px 1fr auto; column-gap: 10px; align-items: baseline; padding: 9px 14px; font-size: 13.5px; line-height: 1.4; }
.dev-step + .dev-step { border-top: 1px solid var(--app-sheet-line); }
/* The mark: a ring, filled ok for a cleared step and blocked for a red one;
   the step waiting on a person wears the attention tone, and the one in
   flight spins the shell's arc. */
.dev-step-mark {
  display: inline-flex; align-items: center; justify-content: center; align-self: start; margin-top: 1px;
  width: 20px; height: 20px; border-radius: 9999px; font-size: 11px; font-weight: 800;
  box-shadow: inset 0 0 0 1.5px currentColor; color: var(--text-muted); background: transparent;
}
.dev-step-mark-done { background: var(--state-ok); color: #fff; box-shadow: none; }
.dev-step-mark-blocked { background: var(--state-blocked); color: #fff; box-shadow: none; }
.dev-step-mark-waiting { color: var(--state-attention); }
.dev-step-mark-active { box-shadow: none; color: var(--accent); }
.dev-step-mark-active > .dc-status-icon { margin: 0; }
.dev-step-label { font-weight: 600; color: var(--text-primary); }
.dev-step-done .dev-step-label { color: var(--text-secondary); }
.dev-step-pending .dev-step-label { color: var(--text-muted); }
/* A step an admin's force merge skips is done, but greyed: it was not cleared. */
.dev-step[data-req-skipped] .dev-step-label { color: var(--text-muted); }
.dev-step-actor { font-size: 12px; color: var(--text-muted); white-space: nowrap; }
.dev-step-body { grid-column: 2 / 4; display: flex; flex-direction: column; gap: 3px; margin-top: 2px; min-width: 0; font-size: 12.5px; color: var(--text-muted); }
.dev-step-body .dev-ledger-text { color: var(--text-secondary); }
.dev-step-blocked .dev-step-body .dev-ledger-text { color: var(--text-primary); }
.dev-step-note { color: var(--text-muted); }
.dev-step-when { color: var(--text-muted); }
.dev-step-body .dev-ledger-fails { font-size: 12px; }
.dev-step-body .dev-ledger-ops { margin-top: 4px; }
.dev-step-body .dev-ledger-help { margin: 0; }
/* The vote's line: the bar to the threshold, the card's pill, the counts. */
.dev-step-vote { display: flex; align-items: center; flex-wrap: wrap; gap: 8px 10px; }
.dev-step-vote-bar { flex: 0 0 160px; height: 8px; border-radius: 999px; background: var(--state-neutral-bg); overflow: hidden; }
.dev-step-vote-bar > i { display: block; height: 100%; border-radius: 999px; background: var(--state-ok); }
.dev-step-vote-tally { color: var(--text-primary); font-weight: 600; font-size: 12.5px; }
/* #3234: the threshold moved during the vote; muted, beside the counts. */
.dev-step-vote-was { color: var(--text-muted); font-size: 12.5px; }

/* ── A merge gate's step: one short line ──
   The mark, the label and the line on one row (app-view.js _stepLine), a
   button only for whoever can clear it. The line takes the step's tone when
   it is waiting on somebody or blocked — the one word a scan is after. */
.dev-step-main {
  display: flex; flex-wrap: wrap; align-items: baseline; gap: 2px 10px; min-width: 0;
  grid-column: 2 / 4;
}
.dev-step-line { font-size: 12.5px; color: var(--text-muted); min-width: 0; }
.dev-step-active .dev-step-line { color: var(--text-secondary); }
.dev-step-waiting .dev-step-line { color: var(--state-attention); font-weight: 600; }
.dev-step-blocked .dev-step-line { color: var(--state-blocked); font-weight: 600; }
.dev-step-main .dev-ledger-review-line { gap: 4px 8px; }
/* Who voted is a list of names, not the step's state: it keeps the muted ink
   whatever the mark says. */
.dev-step-main .dev-ledger-roster.dev-step-line { color: var(--text-muted); font-weight: 400; }
.dev-step-main .dev-ledger-help { margin: 0; }
.dev-step-main .dev-step-vote-was { flex-basis: 100%; font-weight: 400; }
/* The Checks step is a disclosure: the whole row is its control. */
.dev-step-toggle {
  border: 0; background: none; padding: 0; margin: 0; font: inherit; color: inherit; text-align: start;
  cursor: pointer; width: 100%;
}
.dev-step-toggle:hover .dev-step-label { color: var(--accent); }
.dev-step-chev {
  width: 14px; height: 14px; margin-inline-start: auto; align-self: center; flex: none;
  color: var(--text-muted); transition: transform 150ms;
}
.dev-step-toggle[aria-expanded="true"] .dev-step-chev { transform: rotate(90deg); }
@media (prefers-reduced-motion: reduce) { .dev-step-chev { transition: none; } }
/* Reduce motion setting (#6510): the same, when Settings asks for it. */
:where(html[data-motion="reduce"]) .dev-step-chev { transition: none; }
/* The run, open: a row per stage — its name, its bar, its count. */
.dev-step-run {
  display: grid; grid-template-columns: 5.5rem minmax(0, 1fr) auto; gap: 7px 10px; align-items: center;
  margin-top: 6px; padding: 10px 12px; border-radius: 10px; background: var(--bg-secondary);
  font-size: 12px; color: var(--text-muted);
}
.dev-step-run-row { display: contents; }
.dev-step-run-k { color: var(--text-secondary); font-weight: 600; white-space: nowrap; }
.dev-step-run-v { font-variant-numeric: tabular-nums; text-align: end; white-space: nowrap; }
.dev-step-run-v.is-bad { color: var(--state-blocked); font-weight: 600; }
.dev-step-run .dev-ledger-build-bar { flex-basis: auto; height: 8px; margin: 0; gap: 3px; }
.dev-step-run .dev-ledger-build-seg { background: var(--state-neutral-bg); }
.dev-step-run .dev-ledger-build-seg.is-done { background: var(--state-ok); }
.dev-step-run .dev-ledger-build-seg.is-now { background: var(--accent); }
.dev-step-run-track {
  position: relative; display: block; height: 8px; border-radius: 999px; overflow: hidden;
  background: var(--state-neutral-bg);
}
.dev-step-run-track > i { position: absolute; top: 0; bottom: 0; inset-inline-start: 0; display: block; }
.dev-step-run-track > .is-pass { background: var(--state-ok); }
.dev-step-run-track > .is-fail { background: var(--state-blocked); }
.dev-step-run-track.is-busy { animation: dev-ledger-progress-pulse 1.4s ease-in-out infinite; }
@media (prefers-reduced-motion: reduce) { .dev-step-run-track.is-busy { animation: none; } }
/* Reduce motion setting (#6510): the same, when Settings asks for it. */
:where(html[data-motion="reduce"]) .dev-step-run-track.is-busy { animation: none; }
.dev-step-run > .dev-ledger-fails { grid-column: 1 / -1; margin: 2px 0 0; }
.dev-step-run-note { grid-column: 1 / -1; margin: 0; font-size: 12px; color: var(--text-muted); }
@media (max-width: 520px) {
  .dev-step-run { grid-template-columns: 4.25rem minmax(3rem, 1fr) minmax(0, max-content); gap: 7px 8px; }
  .dev-step-run-v { white-space: normal; }
}

/* The hero's status row: the card's pill and Vote button, above the band. */
.dev-topic-hero .dev-card-badges.dev-topic-hero-status { margin-top: 0; }
.dev-topic-hero .dev-topic-hero-status + .gc-card-actions { margin-top: 8px; }

/* ── Technical details, as a sheet over the page ──
   Opened from the ⋯ menu (DetailsSheet); body-mounted, so no frosted sheet
   contains it. A bottom sheet on a phone, a centred card above 720px. */
.dev-details-scrim {
  position: fixed; inset: 0; z-index: 70;
  display: flex; align-items: flex-end; justify-content: center;
  background: rgba(20, 20, 26, .28); backdrop-filter: blur(2px); -webkit-backdrop-filter: blur(2px);
}
.dev-details-card {
  width: min(680px, 100%); max-height: 78vh; overflow: auto; box-sizing: border-box;
  padding: 14px 18px 20px; border-start-start-radius: 22px; border-start-end-radius: 22px; border-end-end-radius: 0; border-end-start-radius: 0;
  background: var(--bg-primary); color: var(--text-primary);
  box-shadow: 0 -12px 40px rgba(0, 0, 0, .22);
}
@media (min-width: 720px) {
  .dev-details-scrim { align-items: center; }
  .dev-details-card { border-radius: 22px; }
}
.dev-details-head { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-bottom: 8px; }
.dev-details-head > .dev-topic-h { margin: 0; }
.dev-details-close {
  display: inline-flex; align-items: center; justify-content: center; width: 30px; height: 30px;
  border: 0; border-radius: 9999px; background: var(--bg-tertiary); color: var(--text-primary); cursor: pointer;
}
.dev-details-card > .dev-topic-details-body { margin: 0; padding: 0; background: none; font-size: 13.5px; line-height: 1.5; }
/* B10b: Details stays mounted while shut (the steps it carries stay on the
   page); the scrim's flex would otherwise outrank the hidden attribute. */
.dev-details-scrim[hidden] { display: none; }
.dev-details-pr { display: flex; align-items: baseline; gap: 10px; margin: 0 0 10px; font-size: 13px; color: var(--text-secondary); }
.dev-details-pr > a { font-weight: 600; color: var(--accent); }
/* The steps sheet sits in the card as its own panel: the card is the
   surface, so the sheet's frost and hairline step aside. */
.dev-details-card .dev-topic-steps { padding: 0; background: none; backdrop-filter: none; -webkit-backdrop-filter: none; box-shadow: none; border-radius: 0; }
.dev-details-part { margin-top: 14px; }
.dev-details-sub { margin: 0 0 6px; font-size: 12px; font-weight: 700; letter-spacing: .06em; text-transform: uppercase; color: var(--text-muted); }
.dev-details-part > .dev-topic-details-body { margin: 0; padding: 0; background: none; font-size: 13.5px; line-height: 1.5; }
/* B10b: the hero's Tested line, in the steps' own marks. A tap opens
   Details at the Checks part. */
.dev-topic-tested {
  display: inline-flex; align-items: center; gap: 8px; margin: 12px 0 0; padding: 0;
  border: 0; background: none; cursor: pointer; font: inherit; font-size: 13.5px; font-weight: 600; color: var(--text-secondary);
}
.dev-topic-tested[data-tested="failed"] { color: var(--state-blocked); }
.dev-topic-tested-mark {
  display: inline-flex; align-items: center; justify-content: center; flex: none;
  width: 20px; height: 20px; border-radius: 9999px; font-size: 11px; font-weight: 800;
  box-shadow: inset 0 0 0 1.5px currentColor; color: var(--text-muted);
}
.dev-topic-tested-mark-passed { background: var(--state-ok); color: #fff; box-shadow: none; }
.dev-topic-tested-mark-failed { background: var(--state-blocked); color: #fff; box-shadow: none; }
.dev-topic-tested-mark-broken { color: var(--state-attention); }
.dev-topic-tested-mark-running { box-shadow: none; color: var(--accent); }
.dev-topic-tested-mark-running > .dc-status-icon { margin: 0; }
.dev-description-dialog { margin: auto; border: 0; border-radius: 20px; width: min(680px, calc(100% - 24px)); max-height: 85dvh; }
.dev-description-dialog::backdrop { background: rgba(20, 20, 26, .5); }
@media (max-width: 480px) {
  .dev-topic-hero { padding: 14px 14px 16px; }
  .dev-topic-hero-title { font-size: 22px; }
  .dev-topic-hero-summary { font-size: 16px; }
  .dev-step-vote-bar { flex-basis: 120px; }
}
#dev-topic-thread #gc-thread-messages {
  margin: 4px 0 0;
  max-width: 900px;
  margin-inline-start: auto;
  margin-inline-end: auto;
  background-color: var(--dc-sheet-fill);
  backdrop-filter: var(--dc-frost);
  -webkit-backdrop-filter: var(--dc-frost);
  border-radius: 26px;
  padding: 12px 14px 14px;
  box-shadow: 0 0 0 1px var(--app-sheet-line) inset;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
#dev-topic-thread #gc-thread-messages::before {
  content: "Discussion";
  display: block;
  font-size: 12px;
  font-weight: 600;
  line-height: 1;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--text-muted);
}
/* "Load earlier" as a quiet pill; the empty line as a muted centred note. */
#dev-topic-thread #gc-thread-earlier {
  height: 26px;
  padding: 0 12px;
  font-size: 12px;
  font-weight: 500;
  color: var(--text-muted);
}
#dev-topic-thread #gc-thread-messages > .text-xs { text-align: center; color: var(--text-muted); }
#dev-topic-thread .gc-msg-system { padding: 2px 12px; font-size: 12px; }
#dev-topic-thread .gc-msg-system-repeat { color: var(--text-faint); }
/* ═══════════════════════════════════════════════════════════════════════
   #4453: A REQUEST'S PAGE, drawn as a Messages reply thread
   (group-chat/thread-shell.tsx `RequestShell`). The "‹ Workshop" chip, then
   ONE sheet, the one Messages opens a reply thread in: its header ("Request
   #N", the category, ⋯), a scroller with the request as the root post
   (dev-board/topic/request-head.tsx) and its replies under "N replies"
   (group-chat/transcript.tsx `RequestRows`), and the thread's composer at
   its foot.

   Messages' tokens are only defined on `.messages-layout` and
   `.dev-ws-discussion`, so they are defined here too, with the same values.
   ═══════════════════════════════════════════════════════════════════════ */
.dev-request {
  --messages-surface: #ffffff;
  --messages-surface-2: var(--bg-secondary);
  --messages-hair: var(--border-light);
  --messages-disc-shadow: 0 1px 2px rgba(0, 0, 0, 0.06);
  display: flex;
  flex-direction: column;
  width: 100%;
  max-width: 780px;
  height: 100%;
  min-height: 0;
  margin: 0 auto;
  padding: 0 12px;
  box-sizing: border-box;
}
.dark .dev-request {
  --messages-surface: var(--dc-raised);
  --messages-surface-2: #3a3a3c;
  --messages-hair: rgba(255, 255, 255, 0.08);
  --messages-disc-shadow: 0 1px 2px rgba(0, 0, 0, 0.4);
}
.dev-request-back { flex: 0 0 auto; display: flex; padding-inline-start: 4px; }
.dev-request-back:empty { display: none; }
.dev-request-back .dev-topic-back { margin: 0 0 12px; }
.dev-request-sheet { flex: 1 1 auto; min-height: 0; display: flex; flex-direction: column; }
.dev-request-bar { flex: 0 0 auto; }
.dev-request-scroll { flex: 1 1 auto; min-height: 0; overflow-y: auto; }
/* THE BAR GETS AN EDGE ONCE THE PAGE SCROLLS UNDER IT (overnight audit R01,
   2 Nov 2026). The bar is the sheet's first row and the scroller its next
   sibling, with nothing between them, so a scrolled page was cut flush
   under the title: the root post's own title (the bar repeats it) read as a
   second copy sliced in half, a line of the words as a stray bar. A hairline
   inside the bar's foot says where the page goes under it. Where scroll
   timelines exist it fades in over the first 12px of scroll, so a page at
   rest keeps its seamless head; elsewhere it is always drawn. Inset, so the
   scroller's text never paints over it. */
.dev-request-bar { box-shadow: inset 0 -1px 0 var(--messages-hair); }
@supports (animation-timeline: scroll()) and (timeline-scope: --a) {
  .dev-request-sheet { timeline-scope: --dev-request-scroll; }
  .dev-request-scroll { scroll-timeline: --dev-request-scroll y; }
  .dev-request-bar {
    animation: dev-request-bar-edge linear both;
    animation-timeline: --dev-request-scroll;
    animation-range: 0 12px;
  }
}
@keyframes dev-request-bar-edge {
  from { box-shadow: inset 0 -1px 0 transparent; }
  to { box-shadow: inset 0 -1px 0 var(--messages-hair); }
}
.dev-request-bar .messages-thread-action { position: relative; }

/* The root post: the request itself. */
.dev-request-root { padding-top: 4px; padding-bottom: 14px; }
.dev-request-title {
  margin: 4px 0 6px;
  font-size: 20px;
  line-height: 1.25;
  font-weight: 700;
  color: var(--text-primary);
  text-wrap: balance;
  overflow-wrap: anywhere;
}
/* The asker's own words: a quote, set apart from what the page says. */
.dev-request-ask {
  margin: 2px 0 0;
  padding-block: 2px 2px; padding-inline: 12px 0;
  border-inline-start: 3px solid color-mix(in srgb, var(--text-muted) 40%, transparent);
}
.dev-request-ask-text { font-size: 15px; line-height: 1.5; color: var(--text-secondary); overflow-wrap: anywhere; }
.dev-request-ask-text .dev-issue-body { font-size: inherit; color: inherit; }
.dev-request-ask-text p,
.dev-request-ask-text .dc-p { margin: 0 0 8px; }
.dev-request-ask-text :is(.dc-h3, .dc-h4, .dc-h5):first-child { margin-top: 0; }
.dev-request-ask-text ul { margin: 0 0 4px; padding-inline-start: 20px; list-style: disc; }
.dev-request-ask-text ol { margin: 0 0 4px; padding-inline-start: 20px; list-style: decimal; }
.dev-request-ask-text strong { color: var(--text-primary); }
/* #5999: the request a close proposal closes, first in its About sheet.
   The row size (15px, 650) rather than the request page's large heading:
   the card above already holds this page's one heading. */
.dev-topic-closes { margin-bottom: 10px; }
.dev-topic-closes-title {
  display: block;
  margin: 2px 0 4px;
  font-size: 15px;
  font-weight: 650;
  color: var(--text-primary);
  text-decoration: none;
  overflow-wrap: anywhere;
}
.dev-topic-closes-title:hover { text-decoration: underline; }

/* The hub's own reveal, in the quote's text column; the caret turns over. */
.dev-request-more.dev-ws-reveal-start { margin-top: 4px; padding-inline-start: 0; width: auto; }
.dev-request-more .dev-ws-reveal-chev { transition: transform 240ms cubic-bezier(.32, .72, 0, 1); }
@media (prefers-reduced-motion: reduce) {
  .dev-request-more .dev-ws-reveal-chev { transition: none; }
}
/* Reduce motion setting (#6510): the same, when Settings asks for it. */
:where(html[data-motion="reduce"]) .dev-request-more .dev-ws-reveal-chev { transition: none; }

/* #4481 and #4482: a request's screenshots (dev-board/topic/request-shots.ts).
   With the experimental C switch on, the blocks that hold one leave the fold
   for `.dev-request-shots`, set like the words. A picture whose link carries
   a C comment's pin (comment-pin/pin-data.ts) shows the comment over it as a
   layer: the pin's square corner on the point, the words in a card beside
   it, and a button on the picture's corner that hides both. The picture
   itself stays clean. `.pin-shot` takes the picture link's box and margin,
   so the layer's percentages land on the image. */
.dev-request-shots { margin-top: 6px; font-size: 15px; line-height: 1.5; color: var(--text-secondary); overflow-wrap: anywhere; }
.dev-request-shots .dev-issue-body { font-size: inherit; color: inherit; }
.dev-request-shots p,
.dev-request-shots .dc-p { margin: 0 0 4px; }
.dev-request-shots strong { color: var(--text-primary); }
/* #6387: hold a picture's or a video's place while it loads, so nothing
   under it jumps. The box is the size the page usually shows one in (512px
   wide, its 320px cap at 16:10) in the status card's plane colour, until
   `data-shot-ready` says the media knows its own shape
   (topic/request-head.tsx RequestWords); then it takes that shape. */
.dev-request-shots .dc-inline-img:not([data-shot-ready]),
.dev-request-shots .dc-inline-video:not([data-shot-ready]) {
  width: 512px;
  max-width: 100%;
  aspect-ratio: 16 / 10;
  background: var(--messages-surface);
}
.pin-shot { position: relative; display: block; width: fit-content; max-width: 100%; margin: 6px 0; }
.pin-shot > .dc-inline-img-link,
.pin-shot > .dc-inline-img { margin: 0; }
.pin-shot-layer {
  position: absolute;
  inset: 0;
  z-index: 1;
  pointer-events: none;
  transition: opacity 160ms ease, visibility 160ms;
}
/* One mark per pin; a request of several comments numbers them. */
.pin-shot-mark { position: absolute; inset: 0; }
/* The button's `data-shown` is the one record of whether it is shown; its words say which press it is (not `aria-pressed`, whose name must not change). */
.pin-shot-toggle[data-shown="false"] + .pin-shot-layer { opacity: 0; visibility: hidden; }
/* direction: physical — the pins mark a POINT ON A PICTURE. `--pin-x` and
   `--pin-y` are percentages of the screenshot itself, and the note's side is
   chosen from that same number, so none of it moves when the prose does:
   pinning a point at 70% across the picture pins it there in Arabic too. */
.pin-shot-pin {
  position: absolute;
  left: var(--pin-x);
  top: var(--pin-y);
  width: 24px;
  height: 24px;
  box-sizing: border-box;
  border: 2px solid #ffffff;
  border-radius: 50% 50% 50% 0;
  background: var(--accent);
  color: var(--accent-ink);
  display: grid;
  place-items: center;
  font-size: 11px;
  font-weight: 800;
  line-height: 1;
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.35);
  transform: translateY(-100%);
}
.pin-shot-note {
  position: absolute;
  box-sizing: border-box;
  width: max-content;
  max-width: min(calc(100% - 8px), max(120px, min(240px, calc(100% - var(--pin-x) - 34px))));
  /* (#60, phone review 23 Nov 2026) The 6px above and below are a
     transparent border, not padding: a line clamp clips at the padding
     box, so padding showed the top of a seventh line under the ellipsis.
     The border is outside that box, and the ground still paints under it. */
  padding: 0 10px;
  border: 6px solid transparent;
  border-inline-width: 0;
  border-radius: 12px;
  background: var(--dc-sheet);
  color: var(--text-primary);
  font-size: 13px;
  font-weight: 500;
  line-height: 1.35;
  text-align: start;
  overflow-wrap: anywhere;
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.18), 0 0 0 1px var(--app-sheet-line);
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 6;
  line-clamp: 6;
  overflow: hidden;
}
/* Right of the pin, or left of the point in the picture's right part; its
   foot level with the point, or its head there near the picture's top. */
/* (#60) Never past the picture's edge: where the room beside the pin is
   narrower than the note's least width (120px), the note moves in to end
   4px inside the picture instead of hanging over the page. */
.pin-shot-mark[data-side="right"] .pin-shot-note { left: max(4px, min(calc(var(--pin-x) + 30px), calc(100% - 124px))); }
.pin-shot-mark[data-side="left"] .pin-shot-note {
  right: max(4px, min(calc(100% - var(--pin-x) + 6px), calc(100% - 124px)));
  max-width: min(calc(100% - 8px), max(120px, min(240px, calc(var(--pin-x) - 10px))));
}
.pin-shot-mark[data-rise="up"] .pin-shot-note { bottom: calc(100% - var(--pin-y)); }
.pin-shot-mark[data-rise="down"] .pin-shot-note { top: var(--pin-y); }
/* direction: logical — the pins point at a picture's own coordinates; the
   button's corner below follows the reading direction again. */
.pin-shot-toggle {
  position: absolute;
  top: 6px;
  inset-inline-end: 6px;
  z-index: 2;
  appearance: none;
  border: 0;
  cursor: pointer;
  font: inherit;
  font-size: 12px;
  font-weight: 600;
  line-height: 1;
  padding: 5px 9px;
  border-radius: 999px;
  color: var(--text-primary);
  background: var(--dc-sheet);
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.2), 0 0 0 1px var(--app-sheet-line);
}
.pin-shot-toggle:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.dark .pin-shot-note,
.dark .pin-shot-toggle { background: var(--dc-raised); }
@media (prefers-reduced-motion: reduce) {
  .pin-shot-layer { transition: none; }
}
/* Reduce motion setting (#6510): the same, when Settings asks for it. */
:where(html[data-motion="reduce"]) .pin-shot-layer { transition: none; }

/* A request's track card drawn from the board's older row keeps its place
   unseen until the fresh row says where the work is (request-head.tsx
   `trackPending`, polish board #12). */
.dev-request-track[data-request-track="pending"] { visibility: hidden; }
/* Done: a muted check ring, no fill. Now: the lit ring and dot. Next: a hairline. */
.dev-request-actions { margin-top: 12px; display: flex; gap: 8px; }
.dev-request-primary {
  appearance: none;
  display: inline-flex;
  align-items: center;
  border: 0;
  cursor: pointer;
  font: inherit;
  font-size: 14px;
  font-weight: 600;
  color: var(--accent-ink);
  background: var(--accent);
  padding: 8px 16px;
  border-radius: 999px;
  text-decoration: none;
}
.dev-request-primary:hover { background: var(--accent-light); }
.dev-request-primary:disabled { opacity: .55; cursor: default; }

/* #5987: "Build it with your own Claude Code", folded under the card's own
   action, which stays the one primary thing on the page. Its link is the
   shared Button primitive's pill (own-agent-link.tsx). */
.dev-request-own-agent { margin-top: 14px; padding-top: 12px; border-top: 1px solid var(--messages-hair); }
.dev-request-own-agent-summary { cursor: pointer; font-size: 13px; font-weight: 600; color: var(--text-muted); }
.dev-request-own-agent-lead { margin: 8px 0 0; font-size: 13px; color: var(--text-muted); }
.dev-request-own-agent-needs-heading { margin: 10px 0 2px; font-size: 13px; font-weight: 600; color: var(--text-primary); }
.dev-request-own-agent-needs { margin: 0; padding-inline-start: 18px; list-style: disc; font-size: 13px; line-height: 1.6; color: var(--text-muted); }
.dev-request-own-agent-check { display: inline-block; width: 14px; height: 14px; margin-inline-start: 6px; vertical-align: -2px; color: var(--text-muted); }
.dev-request-own-agent-add { margin-inline-start: 6px; font-weight: 600; color: var(--accent); }

/* Each spec at its newest version, hanging off the request as a shared item. */
.dev-request-read {
  appearance: none;
  flex: 0 0 auto;
  border: 0;
  cursor: pointer;
  font: inherit;
  font-size: 14px;
  font-weight: 600;
  color: var(--text-primary);
  background: var(--messages-surface-2);
  padding: 7px 14px;
  border-radius: 999px;
}
.dev-request-read:disabled { opacity: .6; cursor: default; }

/* The stream: no sheet of its own (the sheet is the thread's), Messages'
   row metrics, and the viewer's own replies not set apart. No padding under
   it either: the transcript's end is its scroller's 12px, as in every chat
   (`.chat-transcript`, "A chat's foot", 1 November 2026). Its 8px, stacked
   on the scroller's 6px, put 14px under the last reply; on the scroller's
   12px it would have put 20. */
#dev-topic-thread #gc-thread-messages:is([data-language="request"], [data-language="change"]) {
  margin: 0;
  max-width: none;
  padding: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
  display: block;
}
#dev-topic-thread #gc-thread-messages:is([data-language="request"], [data-language="change"])::before { content: none; }
.gc-msg-via { color: var(--text-muted); white-space: nowrap; }
/* Something that happened: one muted line, its glyph in the avatar column. */
#dev-topic-thread #gc-thread-messages:is([data-language="request"], [data-language="change"]) .dev-request-event,
.dev-request-event {
  display: flex;
  align-items: baseline;
  gap: 12px;
  padding: 6px 16px;
  text-align: start;
  font-size: 15px;
  color: var(--text-muted);
}
.dev-request-event-glyph { flex: 0 0 36px; text-align: center; font-size: 15px; }
.dev-request-event-text { min-width: 0; overflow-wrap: anywhere; text-wrap: wrap; }
.dev-request-event-text b { color: var(--text-primary); font-weight: 600; }
/* #7216: a vote's line above the post that carries its reason: the note sits
   with its post, with no gap under it, so the two read as one entry. */
#dev-topic-thread #gc-thread-messages:is([data-language="request"], [data-language="change"]) .dev-request-event.dev-request-vote-note,
.dev-request-event.dev-request-vote-note { padding-bottom: 0; }
/* #7221: the change named on a vote's line ("evan voted no · on Change #N")
   wraps as one piece, so a narrow line never starts with a lone "·". */
.dev-request-vote-note-on { white-space: nowrap; }
/* (#116) The time, and the change it was on, under the sentence. */
.dev-request-event-time { display: block; font-size: 0.8125rem; line-height: 1.35; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.dev-request-event-link {
  appearance: none;
  border: 0;
  background: none;
  padding: 0;
  cursor: pointer;
  font: inherit;
  color: var(--accent);
  font-weight: 600;
  text-decoration: none;
}
.dev-request-event-link:hover { text-decoration: underline; }
@media (max-width: 640px) {
  .dev-request { padding: 0 8px; }
  .dev-request-title { font-size: 18px; }
}

/* ═══════════════════════════════════════════════════════════════════════
   #4455: A CHANGE'S PAGE, the same thread (`.dev-request.dev-change`), with
   the change as its root post (dev-board/topic/change-head.tsx): the title,
   the summary as the request page's quote, one row with the requests it
   addresses and the thanks, then two cards one above the other (Votes, then
   Testing: each its name and figure over its bar, its button beside them and
   one line under), then the Before and after card. Its stream is the
   request page's (`[data-language="change"]` above).

   A bar still moving is drawn in the lit ink; a finished one is full and
   green, with a green check and figure (AGENTS.md, "a finished progress bar
   may be green"): done is good news here, not a state to quieten.
   ═══════════════════════════════════════════════════════════════════════ */
.dev-change-via { margin-inline-start: -4px; color: var(--text-muted); }
.dev-change-stale { margin: 6px 0 0; font-size: 13px; color: var(--text-muted); }
.dev-change-root .dev-topic-hero-more { margin-top: 6px; }
.dev-change-root .dev-change-issues { margin-top: 10px; }

/* The requests it addresses, and the thanks: one row. */
.dev-change-addresses { margin-top: 10px; }
.dev-change-chips {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  column-gap: 6px;
  row-gap: 6px;
}
.dev-change-chips-lead { grid-area: 1 / 1; font-size: 13px; color: var(--text-muted); }
.dev-change-chips-first { grid-area: 1 / 2; min-width: 0; display: flex; align-items: center; gap: 6px; }
.dev-change-chips .dev-topic-issue { flex: 0 1 auto; min-width: 0; max-width: 100%; }
.dev-change-reqs-more { flex: none; }
/* The thanks host is `display: contents`, so the button's wrap is the cell. */
.dev-change-chips .dev-change-thanks { grid-area: 1 / 3; justify-self: end; margin-inline-start: 4px; }
.dev-change-chips:not(:has(.dev-change-chips-first)) .dev-change-thanks { grid-area: 1 / 1 / 2 / -1; justify-self: start; margin-inline-start: 0; }
.dev-change-chips-rest {
  grid-area: 2 / 2 / 3 / -1;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 6px;
  min-width: 0;
}

/* Votes, then Testing: two cards in the Messages surface. */
.dev-change-pair { margin-top: 12px; display: grid; gap: 8px; }
/* 6 Nov 2026 (#6419): on the change's own page the Votes and Testing pair
   keeps the change's own state in sight while the reader scrolls. #6615
   (11 Nov 2026): it does so without changing the page's flow. The cards stay
   at full size where they are (`.dev-change-pair[data-stick]`, in flow and
   never sticky); the one-line rows float in `.dev-change-pair-float`, a
   zero-height sticky holder between the mark and the pair that travels within
   the article's content column and lets go, with no extra code, where the
   change's own content ends above the replies. The strip is absolutely
   positioned, so appearing or going changes no height above or below the
   reader: the first version shrank the pair in place and gave the lost height
   back as a margin, and while the cards updated that made the page jump back
   and forth. Because nothing in the flow resizes, the switch cannot feed
   scroll anchoring, and the pair opts out of being an anchor as well. The
   mark is the 1px sentinel above the pair that says when it has left the top
   of the scroller: it has an area to observe and its -1px margin moves
   nothing, and `-4px` is `.messages-thread-scroll`'s own top padding, as the
   old pin had. `--dc-sheet-solid` is the plane colour for a surface content
   passes behind, so nothing shows through the card's padding or the strip's
   gap. */
.dev-change-pair-mark { display: block; height: 1px; margin-bottom: -1px; }
.dev-change-pair[data-stick] { overflow-anchor: none; }
.dev-change-pair-float { position: sticky; top: -4px; z-index: 10; height: 0; overflow-anchor: none; }
.dev-change-pair-float > .dev-change-pair { position: absolute; inset-inline: 0; top: 0; margin-top: 0; }
.dev-change-pair[data-stuck] { gap: 4px; padding-block: 8px; background-color: var(--dc-sheet-solid); }
.dev-change-pair[data-stuck] .dev-change-gate { padding: 8px 12px; }
.dev-change-pair[data-stuck] :is(.dev-change-bar, .dev-change-gate-facts, .dev-change-gate-note,
  .dev-change-gate-why, .dev-change-gate-fix) { display: none; }
.dev-change-pair[data-stuck] [data-change-gate-line="testing"] .dev-change-gate-act { display: none; }
.dev-change-gate {
  min-width: 0;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  column-gap: 16px;
  padding-block: 12px 12px; padding-inline: 14px 12px;
  border-radius: 16px;
  background: var(--messages-surface);
}
.dev-change-gate-main { min-width: 0; }
.dev-change-gate-act { display: flex; align-items: center; gap: 8px; }
/* A vote button beside the card's figure is not padded out to the board
   button's width, and both its sides are even (#7064). */
.dev-change-gate-act .dev-vote-btn { min-width: 0; padding-inline: 11px; }
.dev-change-gate-head { display: flex; align-items: baseline; justify-content: space-between; gap: 12px; line-height: 1.3; }
.dev-change-gate-name { display: inline-flex; align-items: center; gap: 6px; font-size: 15px; font-weight: 600; color: var(--text-primary); }
.dev-change-gate-check { width: 14px; height: 14px; color: var(--state-ok); stroke-width: 2.5; }
.dev-change-gate-figure { font-size: 13px; color: var(--text-muted); font-variant-numeric: tabular-nums; text-align: end; }
.dev-change-gate[data-tone="ask"] .dev-change-gate-figure { color: var(--accent); font-weight: 600; }
.dev-change-gate[data-tone="done"] .dev-change-gate-figure { color: var(--state-ok); font-weight: 600; }
.dev-change-gate[data-tone="bad"] .dev-change-gate-figure { color: var(--state-blocked); font-weight: 600; }
.dev-change-gate[data-tone="warn"] .dev-change-gate-figure { color: var(--state-attention); font-weight: 600; }
.dev-change-bar { margin-top: 8px; height: 8px; display: flex; gap: 3px; }
.dev-change-bar-seg {
  position: relative;
  height: 100%;
  min-width: 6px;
  border-radius: 999px;
  overflow: hidden;
  background: color-mix(in srgb, var(--text-muted) 16%, transparent);
}
.dev-change-bar-fill { position: absolute; inset-block: 0 0; inset-inline: 0 auto; border-radius: inherit; transition: width 400ms cubic-bezier(.32, .72, 0, 1); }
.dev-change-bar-fill[data-state="moving"],
.dev-change-gate[data-done="false"] .dev-change-bar-fill[data-state="done"] { background: var(--lit-ink); }
.dev-change-gate[data-done="true"] .dev-change-bar-fill[data-state="done"] { background: var(--state-ok); }
.dev-change-bar-fill[data-state="bad"] { background: var(--state-blocked); }
.dev-change-gate-note { grid-column: 1 / -1; margin: 8px 0 0; font-size: 13px; line-height: 1.4; color: var(--text-muted); }
.dev-change-gate-facts { grid-column: 1 / -1; margin-top: 8px; display: grid; gap: 2px; font-size: 13px; line-height: 1.4; color: var(--text-muted); font-variant-numeric: tabular-nums; }
.dev-change-gate-facts p { margin: 0; }
.dev-change-gate-facts [data-change-vote-fact="tally"] { color: var(--text-primary); }
.dev-change-gate-facts [data-ask="true"] { color: var(--accent); font-weight: 600; }
.dev-change-gate-link {
  appearance: none;
  border: 0;
  background: none;
  padding: 0;
  cursor: pointer;
  font: inherit;
  font-weight: 600;
  color: var(--accent);
}
.dev-change-gate-link:hover { text-decoration: underline; }
/* A failed run: what went wrong, in the card's own ink over the muted line,
   then the author's Fix it with the re-run beside it, and a refusal under
   them when the agent could not take it. */
.dev-change-gate-why { grid-column: 1 / -1; margin: 10px 0 0; font-size: 14px; line-height: 1.45; color: var(--text-primary); overflow-wrap: anywhere; }
.dev-change-gate-fix { grid-column: 1 / -1; display: flex; flex-wrap: wrap; align-items: center; gap: 8px; margin-top: 10px; }
.dev-change-gate-fix .gc-vote-btn {
  height: 34px;
  padding: 0 14px;
  gap: 6px;
  font-size: 14px;
  font-weight: 600;
}
@media (prefers-reduced-motion: reduce) {
  .dev-change-bar-fill { transition: none; }
}
/* Reduce motion setting (#6510): the same, when Settings asks for it. */
:where(html[data-motion="reduce"]) .dev-change-bar-fill { transition: none; }

/* The cards' buttons at Messages' size: Preview a neutral pill, the
   re-run the accent one; Vote is the card's own picker button. */
.dev-change-gate-act .gc-vote-btn {
  height: 34px;
  padding: 0 14px;
  gap: 6px;
  font-size: 14px;
  font-weight: 600;
}
.dev-change-gate-act .gc-vote-btn svg { width: 16px; height: 16px; }
.dev-change-gate-act .gc-vote-btn-preview {
  color: var(--text-primary);
  background: var(--messages-surface-2);
  border-color: transparent;
}
.dev-change-gate-act .gc-vote-btn-preview:hover { background: var(--accent-tint); color: var(--accent); }
.dev-change-gate-act .gc-conflict-badge { font-size: 13px; }
/* The thanks, on the Addresses row: a quiet chip, as the row's other chips. */
.dev-change-chips .dev-change-thanks > .gc-vote-btn {
  height: 26px;
  padding: 0 10px;
  gap: 4px;
  font-size: 13px;
  font-weight: 500;
  color: var(--text-secondary);
  background: var(--messages-surface);
  border-color: var(--messages-hair);
}
.dev-change-chips .dev-change-thanks > .gc-vote-btn:hover { color: var(--accent); background: var(--accent-tint); }
.dev-change-chips .dev-thanks-tail { display: none; }
/* The zero chip stays out of the row: kudos.js sets [hidden] on the wrap
   while the count is 0, but its Tailwind inline-block would beat the
   preflight rule, so restate it at this specificity. */
.dev-change-chips .dev-change-thanks[hidden] { display: none; }

/* VERSIONS (docs/plans/versions.md): an update's From <original> card,
   under its summary (change-head.tsx UpstreamCard). A gate card's surface
   and radius; the original's tile and name as a row (15 over 13); what it
   brings, each with the check a finished gate wears; then "In <version>"
   over what it does here, quieter, each on a dot. A line about data it
   would change is in the attention ink, the one thing here that asks. */
.dev-change-upstream { margin-top: 12px; padding: 12px 14px; border-radius: 16px; background: var(--messages-surface); }
.dev-change-upstream-head { display: flex; align-items: center; gap: 10px; }
.dev-change-upstream-tile {
  width: 32px; height: 32px; border-radius: 9px; flex: none; overflow: hidden;
  display: inline-flex; align-items: center; justify-content: center; font-size: 17px; font-weight: 700;
}
.dev-change-upstream-tile > img { width: 100%; height: 100%; object-fit: cover; }
.dev-change-upstream-name { display: block; font-size: 15px; font-weight: 650; line-height: 20px; color: var(--text-primary); overflow-wrap: anywhere; }
.dev-change-upstream-sub { display: block; font-size: 13px; line-height: 18px; color: var(--text-muted); }
.dev-change-upstream-list { margin: 10px 0 0; padding: 0; list-style: none; display: grid; gap: 6px; }
.dev-change-upstream-list li { display: flex; align-items: flex-start; gap: 8px; font-size: 14px; line-height: 19px; color: var(--text-primary); overflow-wrap: anywhere; }
.dev-change-upstream-glyph { width: 15px; height: 15px; flex: none; margin-top: 2px; color: var(--state-ok); stroke-width: 2.5; }
.dev-change-upstream-label {
  margin: 12px 0 0; padding-top: 10px; border-top: 1px solid var(--app-sheet-line);
  font-size: 13px; font-weight: 650; color: var(--text-secondary); overflow-wrap: anywhere;
}
.dev-change-upstream-here { margin-top: 6px; }
.dev-change-upstream-here li { font-size: 13px; line-height: 18px; color: var(--text-muted); }
.dev-change-upstream-dot { width: 5px; height: 5px; margin: 7px 5px 0; border-radius: 999px; flex: none; background: currentColor; opacity: .55; }
.dev-change-upstream-warn, .dev-change-upstream-here li.dev-change-upstream-warn { color: var(--state-attention); }
/* Not for your version?: under Votes and Testing, quieter than either, a
   hairline rather than a fill, its one button a neutral pill. */
.dev-change-upstream-skip {
  margin-top: 8px; padding-block: 10px 10px; padding-inline: 14px 12px; border-radius: 16px;
  border: 1px solid var(--app-sheet-line); display: flex; align-items: center; gap: 12px;
}
.dev-change-upstream-skip-title { display: block; font-size: 14px; font-weight: 600; line-height: 19px; color: var(--text-primary); }
.dev-change-upstream-skip-sub { display: block; margin-top: 1px; font-size: 12px; line-height: 16px; color: var(--text-muted); overflow-wrap: anywhere; }
.dev-change-upstream-skip-actions { flex: none; display: flex; flex-wrap: wrap; justify-content: flex-end; gap: 6px; }
.dev-change-upstream-skip-btn {
  appearance: none; border: 0; cursor: pointer; padding: 7px 12px; border-radius: 999px;
  font: inherit; font-size: 13px; font-weight: 600;
  background: color-mix(in srgb, var(--text-muted) 14%, transparent); color: var(--text-primary);
}
.dev-change-upstream-skip-btn:disabled { opacity: .5; cursor: default; }
/* Ask Homeroom bot to fit it is the action there: the accent's pill. */
.dev-change-upstream-fit-btn { background: var(--accent); color: #fff; }
@media (max-width: 420px) {
  .dev-change-upstream-skip { flex-wrap: wrap; }
  .dev-change-upstream-skip-actions { width: 100%; justify-content: flex-start; }
}

/* Before and after: the card, its title, and the line that says where the shots stand. */
.dev-change-card-name { flex: 1 1 auto; min-width: 0; font-size: 15px; font-weight: 600; color: var(--text-primary); }
.dev-change-shots { margin-top: 8px; border-radius: 16px; overflow: hidden; background: var(--messages-surface); }
.dev-change-shots-plain { padding: 12px 14px 14px; }
.dev-change-shots-line { margin: 8px 0 0; display: flex; align-items: center; gap: 8px; font-size: 14px; color: var(--text-muted); }
/* The previous version's shots keep their picture under a line that says
   whose they are (change-head.tsx PreviousShotsLine): inside the card it
   sits in the card's own padding; over the slider, and over a request
   page's small pair (thread-changes.tsx ShotsPair), it is a line above. */
.dev-change-shots-previous-line { flex-wrap: wrap; }
.dev-change-shots > .dev-change-shots-previous-line { margin: 0; padding: 10px 14px 4px; }
.dev-thread-shots > .dev-change-shots-previous-line { flex-basis: 100%; margin: 0; }
.dev-change-shots-tiles { margin-top: 8px; }
.dev-change-closed-note { margin: 0; padding: 6px 16px 12px; font-size: 15px; color: var(--text-muted); }
/* 1 Nov 2026 (one page per thread): a change on its request's page carries
   what only its own page had. Its ⋯ is the header's disc, smaller, at the
   end of its line beside its status pill. */
.dev-thread-change-menu {
  display: inline-flex; align-items: center; justify-content: center; flex: 0 0 auto;
  width: 32px; height: 32px; border-radius: 9999px; color: var(--text-primary);
  background: var(--messages-surface); box-shadow: var(--messages-disc-shadow); transition: background 150ms;
}
.dev-thread-change-menu:hover { background: var(--messages-surface-2); }
.dev-thread-change-menu svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
.dev-thread-change-menu:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
/* Phone audit (request 7164): the disc stays 32px and its tap area is 44px,
   6px of reach on every side. The line's gap is 8px, so the reach stops
   short of the control before it. */
.dev-thread-change-menu { position: relative; }
.dev-thread-change-menu::after { content: ""; position: absolute; inset: -6px; }
.dev-thread-change-summary { margin-top: 6px; }
.dev-thread-change-summary .dev-request-ask-text { font-size: 14px; }
/* Its before and after, small: two stills side by side, then Expand, which
   opens the before & after viewer in the detail column. */
.dev-thread-shots { margin-top: 8px; display: flex; align-items: flex-end; gap: 10px; flex-wrap: wrap; }
.dev-thread-shots-pair { display: flex; gap: 6px; padding: 0; border: 0; background: none; cursor: zoom-in; border-radius: 10px; }
.dev-thread-shots-pair:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.dev-thread-shot { position: relative; display: block; width: 112px; height: 70px; border-radius: 10px; overflow: hidden;
  background: var(--messages-surface); outline: 1px solid var(--app-sheet-line); outline-offset: -1px; }
.dev-thread-shot img { display: block; width: 100%; height: 100%; object-fit: cover; object-position: top center; }
.dev-thread-shot-none { display: block; width: 100%; height: 100%; }
.dev-thread-shot-label { position: absolute; inset-inline-start: 4px; bottom: 4px; padding: 1px 6px; border-radius: 9999px;
  font-size: 11px; font-weight: 600; line-height: 16px; color: #fff; background: rgba(0, 0, 0, 0.55); }
.dev-thread-shots-expand { padding: 4px 10px; border: 0; border-radius: 9999px; font-size: 13px; font-weight: 600;
  color: var(--text-primary); background: var(--state-neutral-bg); }
.dev-thread-shots-expand:hover { text-decoration: underline; }
/* Competing changes fold under their ballot: a line each, which opens. */
.dev-thread-fold { padding: 8px 0; border-top: 1px solid var(--app-sheet-line); }
.dev-thread-fold:first-child { border-top: 0; }
.dev-thread-fold-head { display: block; padding: 2px 0; border: 0; background: none; border-radius: 8px; }
.dev-thread-fold-head:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
/* A reply written on one of the request's changes says which, after its time. */
.gc-msg-on-change { margin-inline-start: 6px; font-size: 12px; color: var(--text-muted); }
/* #5007: a change built for a request points its replies at the request
   where its conversation lives. The `p` variant sits above the "N replies"
   row; the `div` one replaces the "No replies yet" row and keeps that
   row's hairline. Same spacing and type as the reply-count row. */
p.dev-change-issue-pointer {
  margin: 0;
  padding: 2px 16px 4px;
  color: var(--text-muted);
  font-size: 13px;
}
.dev-change-issue-link { color: var(--accent); font-weight: 600; text-decoration: none; }
.dev-change-issue-link:hover { text-decoration: underline; }

/* Shot details, in the Details sheet. */
.dev-shot-details-claims { margin: 6px 0 0; padding-inline-start: 18px; display: flex; flex-direction: column; gap: 8px; font-size: 13px; }
.dev-shot-details-meta, .dev-shot-details-flow { margin-top: 2px; color: var(--text-muted); }
.dev-shot-details-builds { margin: 10px 0 0; display: flex; flex-wrap: wrap; gap: 6px; font-size: 12px; color: var(--text-muted); }

@media (max-width: 640px) {
  /* The requests take the row's width; the thanks goes on a line of its own. */
  .dev-change-chips { grid-template-columns: auto minmax(0, 1fr); }
  .dev-change-chips .dev-change-thanks { grid-area: 3 / 1 / 4 / -1; justify-self: start; margin-inline-start: 0; }
  .dev-change-chips:not(:has(.dev-change-chips-first)) .dev-change-thanks { grid-area: 1 / 1 / 2 / -1; }
  /* The post's body takes the sheet's width: a small avatar beside the
     name, then the title, the summary and its cards at full width. */
  .dev-change-root { position: relative; display: block; }
  .dev-change-root > [aria-hidden="true"]:first-child {
    position: absolute;
    inset-inline-start: 12px;
    top: 4px;
    width: 24px;
    height: 24px;
    border-radius: 8px;
    font-size: 11px;
  }
  .dev-change-root .messages-message-head { padding-inline-start: 32px; min-height: 24px; align-items: center; }
  /* The card's buttons take a row of their own, under its line, so the
     name, figure and bar keep the card's width. */
  .dev-change-gate { grid-template-columns: minmax(0, 1fr); }
  .dev-change-gate-act { order: 1; flex-wrap: wrap; margin-top: 10px; }
  .dev-change-gate-head { flex-wrap: nowrap; row-gap: 2px; }
  .dev-change-gate-name { flex: none; min-width: 0; }
  .dev-change-gate-figure { min-width: 0; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }
  /* #6419: the stuck pair keeps only the heading, the figure and the vote,
     a little tighter; its note stays on the full card in the thread. The
     Vote button goes back on the card's own line, so the card stays one
     line on a phone as it does on a computer. */
  .dev-change-pair[data-stuck] .dev-change-gate { grid-template-columns: minmax(0, 1fr) auto; padding: 8px 12px; }
  .dev-change-pair[data-stuck] .dev-change-gate-act { order: 0; margin-top: 0; flex-wrap: nowrap; }
}

/* ── The Workshop ──────────────────────────────────────────────────
   features/dev-board/workshop/workshop.tsx. The lander's own chrome:
   the strips above the themes, the theme cards, the rows inside them.
   Colours come
   from the same tokens the session sheet and the cards read, so the
   Workshop is the board's language and not a second one. */
.dev-ws { display: flex; flex-direction: column; gap: 10px; }
.dev-ws-eyebrow {
  font-size: 11px; font-weight: 600; letter-spacing: .06em; text-transform: uppercase;
  color: var(--text-muted);
}
.dev-ws-strip {
  background-color: var(--dc-sheet-fill);
  backdrop-filter: var(--dc-frost);
  -webkit-backdrop-filter: var(--dc-frost);
  border-radius: 22px;
  padding: 12px 14px;
  box-shadow: 0 0 0 1px var(--app-sheet-line) inset;
  display: flex; flex-direction: column; gap: 8px;
}
/* CENTRE, not baseline. Baseline was right while the only thing beside the
   eyebrow was a 22px pill; with a 30px ring in the line the eyebrow's
   baseline aligned to the bottom of the ring and the two read as two rows. */
.dev-ws-strip-head { display: flex; align-items: center; justify-content: space-between; gap: 10px; }
.dev-ws-strip-text { margin: 0; font-size: 14px; color: var(--text-primary); }
/* ── ONE HEADING, FOR EVERY SECTION ON THE TAB ───────────────────────────
   There were two vocabularies doing one job: three panes wore
   `.dev-ws-eyebrow` — 11px, caps, letterspaced, muted — and the fourth wore
   a sentence-case label with a count beside it and an action at its far
   end. The second is the one that reads as a heading; the caps one reads as
   a tag stuck on a box. So it is this, everywhere, and the sections are
   told apart by what they HOLD rather than by four weights of label.

   `.dev-ws-since-head` keeps its own class because it also carries Clear
   and the disabled state that goes with it; the two match by value. */
.dev-ws-head { display: flex; align-items: center; gap: 8px; }
.dev-ws-head-title { font-size: 14px; font-weight: 600; color: var(--text-primary); }
.dev-ws-head-n {
  height: 19px; min-width: 19px; padding: 0 6px; border-radius: 999px;
  background: var(--brand-tint); color: var(--brand-ink);
  font-size: 11.5px; font-weight: 700;
  display: grid; place-items: center;
  font-variant-numeric: tabular-nums;
}
/* A heading's count in words, muted, beside it ("1 open", "2 since your
   last visit"): a phrase, not a pill (After-Workshop-B). */
.dev-ws-head-sub { font-size: 13px; color: var(--text-muted); }
/* ── The general discussion, at the foot of the dashboard pane ───────────
   No pill and no card. A rounded capsule on a rounded pane is a shape
   inside a shape, and this pane already has an internal rhythm — hairline,
   block, hairline — that the weeks above it use. The row joins it: one more
   rule, then the row, full-bleed to the pane's own padding. */
.dev-ws-chat-row {
  display: flex; align-items: center; gap: 9px; width: 100%;
  margin-top: 12px; padding: 12px 0 0;
  border: 0; border-top: 1px solid var(--app-sheet-line);
  background: none; cursor: pointer;
  font: inherit; font-size: 13px; color: var(--text-secondary); text-align: start;
}
.dev-ws-chat-row:hover .dev-ws-chat-said { color: var(--text-primary); }
.dev-ws-chat-row:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; border-radius: 8px; }
/* The glyph keeps the card's chip geometry but drops its tinted plate: on a
   row this size the plate was the largest object in the line. */
.dev-ws-chat-row > .dev-card-icon {
  flex: none; width: 20px; height: 20px;
  background: transparent; border-radius: 0;
}
.dev-ws-chat-row > .dev-card-icon > svg { width: 17px; height: 17px; }
/* TWO LINES: what this is, then the last thing said. The title is the
   row's own name and wraps never; the saying under it is somebody else's
   sentence of any length, and a row that grows to hold it stops being a
   row — so that one clips. */
.dev-ws-chat-text {
  flex: 1 1 auto; min-width: 0;
  display: flex; flex-direction: column; gap: 1px;
}
.dev-ws-chat-title { font-size: 13px; font-weight: 600; color: var(--text-primary); }
.dev-ws-chat-said {
  min-width: 0; font-size: 12.5px; color: var(--text-muted);
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
/* The glyph aligns to the TITLE rather than to the middle of a two-line
   block, which is where a centred row would put it. */
.dev-ws-chat-row { align-items: flex-start; }
.dev-ws-chat-row > .dev-card-icon { margin-top: 1px; }
/* A dated week IS its dates (the since list's headings, workshop.tsx
   SinceWeekBlock), so they take the heading's own weight and ink; the live
   week wears its range as a muted gloss. `tabular-nums` because a column
   of ranges is read down. */
.dev-ws-card-dates { font-variant-numeric: tabular-nums; }
.dev-ws-card-range {
  font-size: 12px;
  font-weight: 500;
  letter-spacing: 0;
  color: var(--text-muted);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
/* ── The pane's reveal control ──────────────────────────────────
   ONE style for "put more of this pane on screen": the step backwards
   through the weeks, and the since-list's "Show 8". They are the same act
   and they were two different objects — the first a left-aligned grey pill,
   the second a grey pill in a lane of left-aligned text — and in both cases
   the pill made the most OPTIONAL thing in its block the most solid-looking
   thing in it.

   Quiet and centred instead: no border, no fill, muted 12px, the accent on
   hover, and a caret pointing the way the content arrives. Centred over
   full-width content rather than hung off one side of it. */
.dev-ws-reveal {
  display: flex; align-items: center; justify-content: center; gap: 5px;
  width: 100%; padding: 3px 8px;
  border: 0; background: transparent;
  font-size: 12px; font-weight: 600; letter-spacing: .01em;
  color: var(--text-muted);
  cursor: pointer;
}
.dev-ws-reveal:hover { color: var(--accent); }
.dev-ws-reveal:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; border-radius: 8px; }
/* There is no ChevronUpIcon in the kit and one caret does not earn a 22nd
   module, so UP is ChevronDownIcon turned over — the same trick the lane
   headings already use on their own chevron.

   Which way it points is which way the content arrives: the week walk grows
   UPWARDS (each press puts an older window above the one you were reading),
   so its caret is always up; the since-list opens DOWNWARDS, so its caret
   points down and turns over once the rows are showing. */
/* Left-aligned, in the lane's own text column.
   Centring is right for the week walk: it sits under a stack of full-width
   cards and belongs to all of them. The since-list's control sits in a lane
   of left-aligned type — a bulleted heading and its note — and centred it
   read as a third, unrelated thing floating mid-lane. Indented to the
   note's 16px so the two share a left edge. */
.dev-ws-reveal-start { justify-content: flex-start; padding-inline-start: 16px; }
.dev-ws-reveal-chev { width: 14px; height: 14px; }
/* ── Since your last visit ───────────────────────────────────
   A HEADING over rows, not a disclosure. It was one collapsed line with a
   caret, on the reasoning that most visits do not need the fact — and what
   that produced was a strip nobody opened: the count said something had
   moved and the rows saying what were behind a press. The bargain is the
   LIST'S LENGTH now (three a week, then a few more a press, and `Show an
   earlier week`), not its existence, which is what the week walk one pane
   up already does with its own history.

   `.dev-ws-since-head` is what `.dev-ws-since-row` was, minus everything
   that said "press me": no pill radius, no pointer, no hover ink, no caret.
   It is the pane's eyebrow, with a count riding it.

   These rules live beside the reveal control the strip shares, not under
   the tab they were first written for. They were born inside the old
   Needs-you block, and #2080, rewriting that tab into a feed, took them out
   with the rest of it — while the strip had already moved to Current status
   in #2065 and its markup went on emitting the classes. Two bare inline
   spans were what was left: "Since your last visit2" (#2097). */
.dev-ws-since-head {
  display: flex; align-items: center; gap: 8px;
  width: 100%; padding: 2px 2px 0;
  font-size: 13px; font-weight: 600;
  color: var(--text-muted); text-align: start;
}
.dev-ws-since-label { flex: 1 1 auto; min-width: 0; }
.dev-ws-since-n {
  flex: none; display: inline-flex; align-items: center; justify-content: center;
  min-width: 20px; height: 20px; padding: 0 6px; border-radius: 999px;
  background: var(--brand-tint); color: var(--brand-ink);
  font-size: 11px; font-variant-numeric: tabular-nums;
}
/* `Show an earlier week` steps the since list back a week: `.dev-ws-reveal`,
   centred, caret down at what it is about to reveal, under a stack of
   full-width rows, so it takes the centred form rather than
   `.dev-ws-reveal-start`'s lane indent.
   #3524: under a week it also takes the week's own hairline, the rule the
   week it reveals will arrive under. It sat bare beneath that week's "N
   more new" before, and the two read as one control said twice; the rule
   puts it outside the week, and the week's own reveal stays inside it
   (`.dev-ws-since-week-more`). "N new" further back rides it in the accent:
   a number that asks for the reader. */
.dev-ws-since-more { margin-top: 2px; }
.dev-ws-since-week + .dev-ws-since-more {
  margin-top: 6px; padding-top: 10px;
  border-top: 1px solid var(--app-sheet-line);
}
.dev-ws-since-more-new { color: var(--accent); }
/* #2183: the control is always drawn and DISABLED when the walk is over,
   rather than leaving — so it reads as spent, not pressable. */
.dev-ws-reveal:disabled { color: var(--text-muted); opacity: .45; cursor: default; }
.dev-ws-reveal:disabled:hover { color: var(--text-muted); }
/* `Clear` rides the far end of the heading row (#2183) — the notifications
   sheet's "Mark all read", drawn the same size as the heading's own type
   and in its muted ink, the accent on hover. Pushed right by its own
   margin so the label and the count keep the gap they had. Disabled when
   there is nothing to clear rather than absent, so the row does not reflow
   between a quiet visit and a busy one. */
.dev-ws-since-clear {
  flex: none; margin-inline-start: auto; padding: 2px 6px;
  border: 0; border-radius: 6px; background: transparent;
  font-size: 12px; font-weight: 600; letter-spacing: .01em;
  color: var(--text-muted);
  cursor: pointer;
}
.dev-ws-since-clear:hover { color: var(--accent); }
.dev-ws-since-clear:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.dev-ws-since-clear:disabled { opacity: .45; cursor: default; }
.dev-ws-since-clear:disabled:hover { color: var(--text-muted); }
/* The line across the list (#2183): where a week's rows cross from what is
   new into what the reader has already seen (#3524: in the same column,
   under the same one reveal, rather than behind a fold of their own). The heading's own shape, one
   size down, with the count of the whole rest riding it in plain ink rather
   than the brand tint — these rows are not news. */
.dev-ws-since-seen {
  display: flex; align-items: center; gap: 8px;
  width: 100%; margin-top: 6px; padding: 2px 2px 0;
  font-size: 12px; font-weight: 600;
  color: var(--text-muted); text-align: start;
}
.dev-ws-since-seen-label { flex: 1 1 auto; min-width: 0; }
.dev-ws-since-seen-n {
  flex: none; display: inline-flex; align-items: center; justify-content: center;
  min-width: 20px; height: 20px; padding: 0 6px; border-radius: 999px;
  background: var(--bg-secondary); color: var(--text-muted);
  font-size: 11px; font-variant-numeric: tabular-nums;
}

/* ── The three destinations ──────────────────────────────────
   A segmented rail pinned to the FOOT of the lander. Sticky rather than
   fixed: it belongs to this surface, releases with it, and `bottom: 0`
   works against #dev-forum-scroll for the same reason the pane head's
   `top: 0` does — that scroller is the reading area.

   `.platform-safe-bar` (app.css, top) adds the device's home-indicator
   inset, which is why no bottom padding is written here. */
/* AGAINST THE BOTTOM, always — and neither `sticky` nor `fixed` does that on
   its own here. Sticky pins a bar only while its own container is taller
   than the view, so on a short Current status it sat wherever the content
   happened to end, halfway up the screen. Fixed was worse: an ancestor of
   this surface carries `backdrop-filter`, which makes it the containing
   block for fixed descendants, so "bottom: 0" meant the bottom of a frosted
   panel rather than of the screen.

   So the LANDER is given the reading area's height (the same viewport
   arithmetic the deck uses) and the bar is pushed to its foot with
   `margin-top: auto`. Sticky on top of that keeps it in view while a long
   tab scrolls under it. */
/* `max(100%, …)`, because neither half works alone. In the NATIVE layout
   #dev-forum-scroll has a definite height, so 100% is exactly the reading
   area. In the BROWSER layout it does not (app.css forces #app-view to
   `height: auto` so the page scrolls), and a percentage min-height against
   an indefinite parent resolves to 0 — which is what left the bar floating
   halfway up a short tab. The viewport arithmetic is the floor under that.

   It subtracts the header and the insets and NOT the tab rail: the rail is
   inside this box, pushed to its foot by the tab body's `flex: 1`.
   Subtracting it here as well was the bug — the lander came out one rail
   short of the space it had, and the bar stopped that far above the
   bottom. */
/* ── The lander fills what is left of the scroller ─────────────────────
   `min-height: max(100%, var(--ws-area))` is what this replaces, and it was
   wrong in a way no amount of tuning the rail could reach: in FIREFOX the
   floor is simply not applied. Measured on the real app (Gecko 155, the
   native layout): `.dev-ws` computed `min-height: max(100%, 806.5px)` and
   used a height of 649px, leaving 121px of unused scroller below it. A
   sticky bar cannot sit below its own parent's bottom edge, so the rail
   rested there and every `--ws-gap` adjustment moved a number that was never
   the problem. Chromium applies the same declaration correctly, which is
   exactly why a headless harness reported 8px while the app floated — the
   percentage inside the `max()` is indefinite here, and the two engines
   disagree about what that makes the whole expression.

   So: NO PERCENTAGE, and two mechanisms, one per layout.

   NATIVE — the scroller has a definite height, so the chain flexes and the
   lander takes what is left of it. Nothing is computed from the viewport, so
   nothing depends on `--platform-header-h` being accurate or on how much
   chrome sits above `#dev-body`; measured, that offset is 47px, which a
   viewport subtraction would have to know and does not. Scoped by `:has()`
   so the other Dev views, which share this scroller, keep their block flow.

   BROWSER-SCROLLER — the scroller is auto-height (app.css forces
   `#app-view { height: auto }` so the page scrolls), so there is no
   remaining space to take and flex gives content height. The viewport floor
   is the right tool there, as a PLAIN LENGTH.

   Both verified against the live app rather than a replica: the same two
   mechanisms, applied by hand in the page, closed the gap from 121px to 9px. */
#dev-forum-scroll:has(> #dev-body > #dev-workshop) { display: flex; flex-direction: column; }
#dev-body:has(> #dev-workshop) {
  flex: 1 1 auto; min-height: 0;
  display: flex; flex-direction: column;
}
/* `width: 100%` IS LOAD-BEARING, not belt and braces. `#dev-workshop` centres
   itself with `margin: 0 auto`, and auto margins on the cross axis of a flex
   column ABSORB the free space instead of stretching — so as a flex item it
   shrank to its content. Measured: the pane went 760 to 640 on By category
   and 1432 to 310 on By stage, which is the column collapsing, not widening.
   With an explicit width the auto margins go back to centring a full-width
   box inside its `max-width`, which is what they did as a block. */
#dev-workshop:has(> .dev-ws) {
  flex: 1 1 auto; min-height: 0; width: 100%;
  display: flex; flex-direction: column;
}
#dev-workshop > .dev-ws { flex: 1 1 auto; width: 100%; }
/* ...AND THE FITTED TAB HAS TO BE ABLE TO SHRINK INSIDE IT. `.dev-ws` is a
   flex ITEM of the chain above, and a flex item's automatic minimum size is
   its CONTENT — every other link here carries `min-height: 0` for that
   reason and this one did not. So on Needs you a long summary did not make
   `.dev-ws-needs-scroll` scroll: the deck refused to shrink, the lander grew
   instead, and the answers and the ask box went down with it. Measured at
   402x874 against a nine-paragraph summary: `.dev-ws` 1803px tall with the
   composer 910px below the fold, in the NATIVE layout — the one whose
   definite scroller was supposed to bound it — and at a 34px inset as well
   as at none.
   ONLY THAT TAB, and a topic's channel. The Discussion (#general's posts,
   26 Nov 2026) is a page that grows like the Hub. The other two are meant to grow: #dev-forum-scroll is the
   scroller they scroll in, and `.dev-ws-tabbody` is not a scroller itself,
   so shrinking them to the viewport would clip what they hold rather than
   make it reachable. */
#dev-workshop > .dev-ws[data-ws-tab="needs"],
#dev-workshop > .dev-ws[data-ws-tab^="c:"] { min-height: 0; }
/* …AND ON THE TWO TABS THAT GROW, THE LINKS ABOVE MUST NOT SHRINK (#3053).
   `min-height: 0` on #dev-body and #dev-workshop is what lets Needs you be
   bounded; on Current status and All items it let both shrink to the
   scroller's height while `.dev-ws` kept its content height and overflowed
   them. A scroller's block-end padding is added after its in-flow CHILDREN,
   not after a descendant that overflows one, so `.platform-safe-scroll` on
   #dev-forum-scroll reserved nothing: at max scroll the last item's foot sat
   exactly at the screen's bottom edge, under the fixed tab bar, with no way
   to scroll it clear. Native layout only — in the browser layout the
   scroller is auto-height and nothing shrinks. `flex-shrink: 0` keeps the
   grow (the lander still fills a short tab) and gives the padding back. */
#dev-body:has(> #dev-workshop > .dev-ws:not([data-ws-tab="needs"]):not([data-ws-tab^="c:"])),
#dev-workshop:has(> .dev-ws:not([data-ws-tab="needs"]):not([data-ws-tab^="c:"])) { flex-shrink: 0; }
html[data-browser-scroller] .dev-ws { min-height: var(--ws-area); }
/* ── A SHORT TAB STILL HAS SOMETHING TO SCROLL (#3520) ──────────────────
   "Unable to over scroll down on hub page (but can on workshop)", in the
   installed iPhone app: on the Hub neither end rubber-banded and a pull from
   the top did not stretch, while the Workshop tab of the same page did both.

   Nothing on the Hub turns the gesture off. Measured in the installed layout
   at 390x844 (standalone, an iPhone's agent): both tabs scroll in the one
   #dev-forum-scroll, with the same overflow (auto), overscroll (contain) and
   touch-action (auto) on it and on every ancestor; neither holds a nested
   scroller, a touch-action or an overscroll rule of its own; and the kit's
   pull binds to the scroller on both. What differs is the RANGE. The chain
   above fills the scroller whenever a growing tab is shorter than the screen
   ("the lander still fills a short tab"), to exactly its height and not a
   pixel more: the Hub measured scrollHeight 799 against clientHeight 799,
   nothing to scroll, and so did a fresh project's Workshop tab. The Workshop
   tab the report compares against is the one that runs past the screen once
   a project has history. iOS only rubber-bands a box that can scroll; one
   with no range hands the drag to the document, which the installed shell
   holds still on purpose (`html, body`: `overflow: hidden`,
   `overscroll-behavior-y: none`), so neither end moved.

   So a growing tab is always ONE PIXEL taller than the scroller: a 1px box
   hung 1px below the scroller's bottom edge, which puts that pixel into its
   scrollable overflow whatever the content does. The same range a long tab
   has, so the same bounce at both ends and the same pull at the top as the
   Workshop's. Past the fold it is a transparent pixel in the middle of the
   content and changes nothing.

   ABSOLUTE, AND OFFSET FROM THE SCROLLER'S OWN EDGE, because the two
   obvious ways cannot work here. A 1px spacer in flow is a flex item of this
   chain, and the grow above takes it back: the lander fills what is left and
   the total stays the scroller's height. `min-height: calc(100% + 1px)` is a
   percentage floor in this chain, which is exactly what Firefox dropped (the
   note above). An absolute box's offsets are against its containing block's
   padding box, which is definite in every engine, so the scroller becomes
   that block (`position: relative`, no z-index: no new stacking context; and,
   measured on all three growing tabs, nothing inside it was positioned
   against anything further out). Nor does
   it touch the scroller's bottom padding, the tab-bar clearance #3053 relies
   on.

   ONLY WHERE IT BOUNCES AND ONLY WHERE THIS IS THE SCROLLER: a phone
   (`pointer: coarse` under 700px; a pixel of range would put a scrollbar on
   a desktop window, and from 700px a scrolled strip draws its pinned band),
   and not in a phone browser, where the document scrolls
   (`data-browser-scroller`) and the pixel would lengthen the page. Not Needs
   you or Discussion either: those are fitted on purpose and scroll inside. */
@media (max-width: 699.98px) and (pointer: coarse) {
  html:not([data-browser-scroller]) #dev-forum-scroll:has(> #dev-body > #dev-workshop > .dev-ws:not([data-ws-tab="needs"]):not([data-ws-tab^="c:"])) {
    position: relative;
  }
  html:not([data-browser-scroller]) #dev-forum-scroll:has(> #dev-body > #dev-workshop > .dev-ws:not([data-ws-tab="needs"]):not([data-ws-tab^="c:"]))::after {
    content: '';
    position: absolute; inset-inline-start: 0; bottom: -1px;
    width: 1px; height: 1px;
    pointer-events: none;
  }
}
/* The tab body takes the space the tabs above it leave. */
.dev-ws-tabbody {
  flex: 1 1 auto; min-height: 0;
  display: flex; flex-direction: column; gap: 10px;
}
.dev-ws-tabs {
  /* AT THE HEAD OF THE PAGE, IN FLOW (#2767). On a phone this was a pill
     FIXED to the foot of the window, which took a portal out of the Dev
     frame's frost to achieve, a token for its box, a token for the air under
     it and a clearance on every tab so content could scroll out from beneath
     it. The owner moved it to the top, under the header, where the app
     switcher drops down from — and there it is simply the first thing in the
     column, taking its own space, overlaying nothing.

     That also ended #2769: the portal's anchor lived outside #app-view, so
     hiding the app view for Messages, Discover or Me left the pill on screen.

     RELATIVE, not static: the bar is the containing block for the selection
     marker and the element workshop.tsx measures `offsetLeft`/`offsetTop`
     against. Not sticky: the pane head below it is the part that pins, and
     two sticky bands at `top: 0` would stack on each other.

     A ROW, NOT A SURFACE (#2934). This was the pill itself, with the "+" as
     its last cell, and the "+" read as a fourth tab. The pill's material
     moved onto its two items (the tab list and the "+", below), and this gap
     is the air between them. */
  order: 0;
  position: relative;
  display: flex; gap: 6px;
}
/* A GLYPH BESIDE ITS LABEL, 40px tall. It was a glyph OVER its label, 58px,
   while this was a thumb bar at the foot of the window; at the head of the
   page it is a segmented control — the shape the wide layout already draws —
   and a 72px band there would spend a sixth of a phone's height before the
   first card. 40 still clears the shell's 44px minimum once the pill's own
   padding is counted, and the glyph still carries the scanning if a label
   has to ellipsize on the narrowest phone. */
.dev-ws-tab {
  /* CONTENT-WEIGHTED, not equal thirds: "Current status" is twice "All
     items", and three equal cells ellipsized it at 390px while the other two
     sat in air. The spare width is still shared out, so the pill stays full.
     THE "+" TAKES A 50px CIRCLE AFTER THE PILL, 6px off it (#2934; it was a
     40px cell inside it), and the tabs pay for it out of their own padding
     (8px to 4px a side) and glyph gap (5px to 4px), not out of their labels:
     at 400px, the narrowest width that draws the glyphs, measured in the
     headless harness's DejaVu Sans — wider than SF Pro or Roboto — the three
     labels need 316px at rest and the pill leaves them 322, so "Current
     status" is still whole beside the "+" and the spare 6px is shared back
     out. */
  flex: 1 1 auto; min-width: 0;
  display: inline-flex; flex-direction: row;
  align-items: center; justify-content: center; gap: 4px;
  height: 40px; padding: 0 4px;
  border: 0; border-radius: 999px;
  background: transparent;
  color: var(--text-muted);
  font: inherit; font-size: 12px; font-weight: 600; letter-spacing: .01em;
  white-space: nowrap; overflow: hidden;
  cursor: pointer;
}
/* THE TRACK IS INERT ON A PHONE. `.dev-ws-tabs` is itself the full-width
   row there, so the wrapper the desktop layout needs must not introduce a
   box. `display: contents` removes it from the layout entirely and its two
   children — the tab list and the "+" — are the nav's flex items. */
.dev-ws-tabtrack { display: contents; }
/* THE TAB LIST takes the row's width less the "+" and the gap before it. A
   real box at both widths (the `tablist` role lives here, and a role on a
   `display: contents` node is one some screen readers drop), and not
   positioned: the tabs' `offsetLeft` must keep resolving against the nav,
   where the marker is. 2px between segments, the desktop track's own step. */
.dev-ws-tablist { flex: 1 1 auto; min-width: 0; display: flex; gap: 2px; }
/* ── The "+", ending the strip ───────────────────────────────────────
   The prototype's `.tplus`: the last item of the tab row, a bare glyph in the
   selected tab's ink, drawn in the strip's own material so it reads as part
   of the strip rather than as a floating action (it was a violet filled
   square at the end of All items' search row). The tab's own height and
   radius; the MARKER's tint and ring when its menu is open, which is how the
   strip already says "this one is active".
   The wrapper is the dropdown's containing block (actions-row.tsx hangs
   `#dev-plus-menu` off its right edge). */
.dev-ws-plus { position: relative; flex: none; display: flex; }
/* TWO SURFACES, ONE ROW (#2934). The pill's material — padding, hairline,
   fill, rounding — is drawn by the tab list and by the "+"'s wrapper rather
   than by the nav, so the "+" is a round button of its own, a gap after the
   pill, instead of a fourth cell inside it. Everything else is #2914's: the
   same row, the same place, the same metrics. The "+" still sits in a 4px
   ring as a tab does, its tint lands where the marker would, and the row is
   as tall as the pill was (1 + 4 + 40 + 4 + 1).
   ONLY THE STRIP'S "+": the unreachable Board still renders the same
   wrapper at the end of `#dev-actions`, and that surface stays unchanged.
   NO FROST HERE, on purpose: a backdrop-filter makes the tab list a
   stacking context, and the marker, painted before it at `z-index: 0`,
   would go under its fill. `--dc-frost` is `none` everywhere anyway. */
.dev-ws-tablist, .dev-ws-tabtrack > .dev-ws-plus {
  padding: 4px;
  border-radius: 999px;
  border: 1px solid var(--app-sheet-line);
  background-color: var(--dc-sheet-fill);
}
.dev-ws-plus-btn {
  display: inline-flex; align-items: center; justify-content: center;
  width: 40px; height: 40px; padding: 0;
  border: 0; border-radius: 999px;
  background: transparent;
  color: var(--lit-ink);
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}
/* Hover only where there IS hover: on touch a tapped button keeps `:hover`
   until the next tap elsewhere, which would leave the "+" tinted after the
   action sheet closes. */
@media (hover: hover) {
  .dev-ws-plus-btn:hover { background: var(--lit-tint); }
}
.dev-ws-plus-btn[aria-expanded="true"] {
  background: var(--lit-tint);
  box-shadow: inset 0 0 0 1px var(--lit-line);
}
.dev-ws-plus-glyph { width: 20px; height: 20px; stroke-width: 2.2; flex: none; }
/* Size lives here, not on the component: icons.tsx has no size variant by
   design, so every call site passes its own class. `flex: none` so a label
   that is trying to fit squeezes itself, not the glyph. */
.dev-ws-tab-glyph { width: 16px; height: 16px; flex: none; }
/* UNDER 400px THE LABELS WIN THE WIDTH. The three labels and their glyphs
   need 316px beside the "+", which a 400px phone has and a 360-390px one
   does not: there "Current status" came out "Current sta…" with its glyph
   still whole, which spends the width on the half a reader cannot read.
   Without the glyphs the labels fit whole down to 340px in DejaVu Sans, and
   down to 320px in Arial's metrics, which are close to SF Pro's and Roboto's. */
@media (max-width: 399px) {
  .dev-ws-tab-glyph { display: none; }
}
.dev-ws-tab-label { min-width: 0; overflow: hidden; text-overflow: ellipsis; }
/* #2915: THE DOT ON ALL ITEMS, while its search or filters are on. They
   narrow that tab alone, so from the other two this is the only sign a search
   is still waiting there. The accent, not the tab's ink: it is a state of the
   tab rather than part of its label, and it has to read on the selected tab's
   tint as well as on the bare track.
   ON A PHONE IT IS A BADGE ON THE GLYPH, AND TAKES NO WIDTH. The pill leaves
   the three labels 8px to spare at 390px (see `.dev-ws-tab`), and a dot after
   the label costs 10: every label lost its last letters to an ellipsis. So it
   is moved to the head of the tab (`order`), its own width and the gap after
   it are handed back (`margin-right`), which lays the glyph over it, and it is
   drawn at the glyph's top-right corner. A transform, so none of that moves
   anything else. Above 700px it goes back after the label, where the segment
   hugs its content and has the room. */
.dev-ws-tab-dot {
  flex: none;
  width: 6px; height: 6px;
  border-radius: 999px;
  background: var(--accent);
  order: -1;
  margin-inline-end: -10px;
  transform: translate(12px, -8px);
}
/* THE ACCENT, not black and no longer the header's periwinkle: `--lit-ink`
   on `--lit-tint` with a hairline of `--lit-line`, the phone's tab bar's own
   lit state, because this is the same kind of thing: where you are, among
   the places you could be. A black pill was the only flat-black object on the
   screen and read as a different product; the periwinkle beside the action
   blue was a second blue for nearly the same meaning.
   The tokens carry their own dark values, so there is no dark variant. */
/* THE INK STAYS ON THE TAB; THE FILL MOVED TO THE MARKER. A background drawn
   by the selected tab itself cannot travel — it can only appear on one and
   vanish from another, which is the snap this replaces. One element that slides
   is the whole idea, so the tab is left with the colour change, which has
   nothing to animate between. */
.dev-ws-tab[aria-selected="true"] {
  color: var(--lit-ink);
}
/* Above the marker, which is painted first and sits at the floor of the
   stacking context. `position: relative` is what puts them on that ladder at
   all — without it the tabs and the marker are both static and the marker,
   coming later in paint order for positioned elements, would cover the
   labels. */
.dev-ws-tab { position: relative; z-index: 1; }
/* WHILE THE "+" MENU IS OPEN the strip outranks the pane head below it. The
   dropdown hangs out of the strip over the tab body, and the strip is a
   stacking context (sticky at `z-index: 30` above 700px), so the menu's own
   `z-30` counts only inside it — and the pane head, which pins at `z-index:
   31` wide and 20 narrow, painted over the menu's rows on All items. Only
   while it is open: at rest the head keeps its place above the strip. A
   click there while the menu is up lands on the strip and dismisses the
   menu, like any outside click. */
.dev-ws-tabs:has(#dev-plus-menu:not(.hidden)) { z-index: 32; }
/* THE MARKER. Every number it uses is measured off the live tab (see
   workshop.tsx), so this rule carries no geometry — which is what lets it
   serve the phone's 58px equal-width pill and the desktop strip's 32px
   content-width segments without a breakpoint of its own.

   `top: 0; left: 0` and then translated: the transform is the only thing that
   moves, and a transform is the one property that animates without asking the
   layout engine anything. */
.dev-ws-tab-marker {
  position: absolute;
  top: 0; inset-inline-start: 0;
  z-index: 0;
  border-radius: 999px;
  background: var(--lit-tint);
  box-shadow: inset 0 0 0 1px var(--lit-line);
  pointer-events: none;
  /* Hidden until measured — see the note in workshop.tsx. */
  opacity: 0;
}
.dev-ws-tab-marker[data-ws-marker-at] { opacity: 1; }
/* THE TRANSITION IS ON A SECOND ATTRIBUTE, and `data-ws-marker-slide` is not
   `data-ws-marker-at`. `at` means MEASURED, which is what the opacity above
   waits for; `slide` means the measurement was caused by the SELECTION
   CHANGING. Only the second is worth animating, and keeping them apart is
   what stops a re-measure of the tab you are already on from replaying the
   slide — see useTabMarker in workshop.tsx, which owns the distinction.

   Both were one attribute, and that conflated three things the marker does.
   The first placement was one: `at` arrives in the same commit as the
   transform, so the transition was live for a change from `none` at zero
   width, and the marker slid in from the nav's left edge on every cold open
   of the All items tab — the exact slide-in the null-until-measured render
   was written to avoid, reintroduced by the rule meant to enforce it. A
   re-measure was the other: any layout shift under the bar re-expressed an
   unmoved tab in new coordinates and the marker animated to where it already
   was. Neither is a selection changing, and neither carries `slide`.

   `width` and `height` are in the list because the desktop segments are
   content-width: "Current status" and "Needs you" are different sizes, so a
   transform alone would slide a box of the wrong width. On the phone all
   three match and those two properties simply never change. */
@media (prefers-reduced-motion: no-preference) {
  .dev-ws-tab-marker[data-ws-marker-slide] {
    transition:
      transform .26s cubic-bezier(.32, .72, 0, 1),
      width .26s cubic-bezier(.32, .72, 0, 1),
      height .26s cubic-bezier(.32, .72, 0, 1);
  }
}
/* Reduce motion setting (#6510): none of the motion above, when Settings asks for it. */
:where(html[data-motion="reduce"]) .dev-ws-tab-marker[data-ws-marker-slide] { transition: none; }

/* ── Needs you: one question, the whole screen ───────────────
   SIZED FROM THE VIEWPORT, not from its ancestors — and that is the second
   attempt. The first was a `height: 100%` chain down from #dev-forum-scroll,
   which has a definite height in the native layout and resolves perfectly
   there. It resolves to nothing in the BROWSER layout: when the root carries
   `data-browser-scroller="dev-forum-scroll"` the rule near the top of this
   file forces `#app-view` to `height: auto !important` so the page itself
   scrolls, and every 100% below it collapses to content height. Two shipped
   layouts, and the chain only worked in one.

   So the deck measures the viewport and subtracts the chrome it can name:
   the platform header, the device insets and the platform's own tab bar.
   `min-height` keeps it usable on a short window rather than letting the
   subtraction win. */
.dev-ws {
  /* THE AIR AT THE FOOT, decided once. The device inset is NOT in this
     number: `#dev-forum-scroll` carries `.platform-safe-scroll`, whose
     padding already reserves the larger of the home-indicator strip and the
     platform's tab bar, and counting either again here is the double spend
     that once left a whole indicator of dead air on a real iOS PWA (the
     headless harnesses report a zero inset and could not see it).

     WHAT IS NOT SUBTRACTED ANY MORE: a Workshop tab bar. On a phone that bar
     floated fixed at the foot of the window, out of flow, so this floor took
     its box and the air under it off by hand. It sits at the head of the page
     now (#2767), in flow INSIDE this box, so the flex chain accounts for it
     and the floor must not take it off a second time — the arithmetic the
     wide layout has always used, at every width.

     THE FIXED STRIPS ABOVE THE HEADER ARE CHROME TOO (QA 2026-09-24 Q8).
     `--browser-banner-h` is the install strip plus the offline strip,
     whichever are up. Body padding reserves them at the head of the page,
     so the page starts that much lower and this floor has to give the same
     length back. Without it a phone browser showing "Get the app" pushed
     the foot of every Needs you card, its chips and the rail's More, under
     the tab bar. The token is 0 with no strip up, hence the fallback; since
     2 Nov 2026 it is declared on every screen (L01), not only the paged ones. */
  --ws-area: calc(
    100dvh - var(--browser-banner-h, 0px)
    - var(--platform-header-h, 56px) - var(--platform-safe-top, 0px)
    - var(--ws-gap) - max(var(--platform-tabs-h, 0px), var(--platform-safe-bottom, 0px))
  );
  /* THE FITTED BOX Needs you takes as a definite height in the browser
     layout (below). While a pill floated over the foot of every tab this was
     a different number from the floor above — the pill overlaid the last
     stretch of it and the tab body's clearance held content off it. Nothing
     overlays the lander now, so the box and the floor are the same length. */
  --ws-fit: var(--ws-area);
}
/* ── Needs you is a FITTED SCREEN on a phone, in both layouts ──────────
   In the NATIVE one #dev-forum-scroll has a definite height, the flex chain
   bounds the deck, and `.dev-ws-needs-scroll` is what takes a long card — so
   the answers, the page arrows and the ask box are pinned.

   In a mobile BROWSER the page itself scrolls (`html[data-browser-scroller]`,
   see browser-scroll.ts), #dev-forum-scroll is `height: auto`, and every
   height below it resolves to content. `--ws-area` is only a FLOOR there, so
   it could not stop a long card growing the deck. So the tab takes `--ws-fit`
   as a definite HEIGHT — the box the native chain arrives at on its own.

   Scoped to the phone as well as to the layout: `data-browser-scroller` is
   set on any coarse pointer (MOBILE_PAGE_QUERY), tablets included, and above
   700px the deck is content-sized at the top of the column instead. 700px is
   the same decision as the `@media (min-width: 700px)` block below and as
   workshop.tsx's `WIDE_QUERY`. */
@media (max-width: 699.98px) {
  html[data-browser-scroller] .dev-ws[data-ws-tab="needs"] {
    height: var(--ws-fit);
    min-height: var(--ws-fit);
  }
}
/* ═══════════════════════════════════════════════════════════════════════
   NEEDS YOU: A FEED OF DECISIONS. One item per screen, the rail of
   actions at the right edge, sheets over the item. workshop.tsx's NeedsFeed
   header is the argument; this is the geometry.

   THE LANDER IS THE STAGE. `.dev-ws-needs` takes what is left between the
   head of the tab and the pill's clearance (the flex chain above, with
   `--ws-fit` on a phone), and the SCROLLER inside it is the snap container:
   every item is exactly its height, `scroll-snap-type: y mandatory` finishes
   any drag on an item boundary, and nothing inside an item scrolls — a long
   summary clamps and the title links to the full page.
   ═══════════════════════════════════════════════════════════════════════ */
.dev-ws-needs {
  flex: 1 1 auto; min-height: 320px;
  position: relative;
  display: flex; flex-direction: column;
}
.dev-ws-needs-scroll {
  flex: 1 1 auto; min-height: 0;
  overflow-y: auto; overscroll-behavior: contain;
  /* #3052: a swiped card travels sideways; the feed must not scroll with it. */
  overflow-x: hidden;
  scroll-snap-type: y mandatory;
  scrollbar-width: none;
  border-radius: 20px;
}
.dev-ws-needs-scroll::-webkit-scrollbar { display: none; }
@media (prefers-reduced-motion: no-preference) {
  .dev-ws-needs-scroll { scroll-behavior: smooth; }
}
/* Reduce motion setting (#6510): none of the motion above, when Settings asks for it. */
:where(html[data-motion="reduce"]) .dev-ws-needs-scroll { scroll-behavior: auto; }
/* #4754: THE STAGE. The strip and the scroller share one column, so the
   strip is as wide as the card and sits over it, and neither scrolls. */
.dev-ws-needs-stage {
  flex: 1 1 auto; min-height: 0;
  display: flex; flex-direction: column;
}
/* Where you are, on the page: one segment an item, lit up to the one in
   view. The gaps are a mask, so the count is a number on the line
   (`--ws-n`) rather than an element an item. The page's own colours: the
   base is the sheet hairline and the lit part the ink that marks where you
   are (--lit-ink), where the card drew the line white on the dark. */
.dev-ws-needs-progress {
  flex: 0 0 auto;
  display: flex; align-items: center; gap: 12px;
  height: 20px; margin: 0 6px 6px;
}
.dev-ws-needs-progress-line {
  flex: 1 1 auto; height: 3px; border-radius: 3px;
  background: var(--app-sheet-line);
  -webkit-mask-image: repeating-linear-gradient(90deg, #000 0 calc(100% / var(--ws-n, 1) - 4px), transparent calc(100% / var(--ws-n, 1) - 4px) calc(100% / var(--ws-n, 1)));
  mask-image: repeating-linear-gradient(90deg, #000 0 calc(100% / var(--ws-n, 1) - 4px), transparent calc(100% / var(--ws-n, 1) - 4px) calc(100% / var(--ws-n, 1)));
}
.dev-ws-needs-progress-line > i { display: block; height: 100%; background: var(--lit-ink); }
.dev-ws-needs-of {
  flex: none;
  font-size: 11px; font-weight: 700; letter-spacing: .06em; color: var(--text-muted);
  font-variant-numeric: tabular-nums; white-space: nowrap;
}
.dev-ws-item-touched { margin: 0; font-size: 13px; line-height: 1.45; color: var(--text-muted); }
/* A request's number on a change's page (topic-head.tsx) is a chip. */
.dev-ws-chip {
  display: inline-flex; align-items: center; height: 24px; padding: 0 9px;
  border-radius: 9999px; font-size: 12px; font-weight: 600; white-space: nowrap;
  background: var(--state-neutral-bg); color: var(--text-secondary);
}
.dev-ws-chip-info { background: var(--accent-tint); color: var(--accent-wash-ink); }
/* The Communities screen's two views (Current status | Needs you,
   `.workshop-scope-tabs`) are gone with the UI overhaul: the list is the
   page, and Needs you is a row at its top that opens the feed below. */
/* ── The Communities screen's Needs you feed (#3270, workshop/needs-reel.tsx) ──
   A project's own Needs you feed since #3488 (NeedsFeed, the stage and the
   item above), in a box a screen tall less the bars around it: the page head
   over it and the tab bar under it. Each item leads with the project it
   belongs to, its tile and its name, a door to its hub. */
.workshop-needs-feed {
  /* NO HEIGHT HERE ANY MORE (#3516): the phone takes it from the flex chain
     below and the desktop from its own rule after that. `min-height` is the
     floor for both: a feed shorter than this is not usable, and on a window
     that short the screen scrolls instead. */
  min-height: 360px;
  margin: 4px 16px 0;
  display: flex; flex-direction: column;
}
/* #6199: the vote-type chips sit INSIDE this box, above the deck, so the feed
   is still the pane's one child (tests/communities-followups.test.js, #3516).
   The box already carries the page's inset, so the rail's own 16px would set
   the chips 16px in from the card's edge; they line up with it instead. */
.workshop-needs-feed > .needs-vote-chips { padding-inline: 0; }
/* ON A PHONE THE FEED ENDS WHERE #workshop-screen'S CLEARANCE BEGINS (#3516).

   It was `height: calc(100dvh - 180px - var(--browser-banner-h, 0px))`: the
   page head and the header over it (116px) and a 56px tab bar with 8px of air
   under it, measured once in a browser with no insets and nothing parked. Three
   things at the foot of a phone were not in that number, and each one put the
   feed's foot under the bar:

   - THE PARKED APP'S STRIP. `--platform-tabs-h` counts it (52px more) the
     moment an app is parked; this number never did. Measured at 390x844 with
     an app parked: the feed ran to 828px against a strip whose top was at
     736 in a phone browser, and to 827 against 716 in the installed layout,
     so the rail's Try it and More and the item's caption sat under the
     strip and the bar.
   - THE INSTALLED APP'S INSETS. An iPhone install reserves the status bar
     at the top (`--platform-safe-top`, 47-62px) and the bar spends part of
     the home indicator at the foot (`--platform-tabs-inset`). Nothing
     parked, the feed still ended 60px under the bar there.
   - THE "GET THE APP" BANNER in a phone browser. `--browser-banner-h` was
     declared only on `html[data-browser-scroller]` routes then, and this
     screen is not one (browser-scroll.ts `PAGES`): its root scrolls itself in
     every layout, so the token read 0 here while the banner pushed the page
     48px down.

   And the foot could not be scrolled into view. `.dev-ws-needs-scroll` is
   `overscroll-behavior: contain`, so a drag on the feed moves between items
   and never reaches the screen behind it; only a drag on the page head moved
   the page.

   SO NO ARITHMETIC: THE SCROLLER'S OWN CLEARANCE BOUNDS IT. #workshop-screen
   is a flex child of the fixed-height body column in both layouts, so it has
   a definite height, and it carries `.platform-safe-scroll`, whose padding is
   `max(--platform-tabs-h, --platform-safe-bottom)`: the tab bar, the parked
   strip when there is one and the home indicator, each counted once, by the
   same token every other screen clears them with. While the feed is up the
   screen, its column and the pane become a flex chain and the feed takes
   what is left above that padding, less `--ws-gap` of air — the line a
   project's own Needs you deck ends on (`.dev-ws`'s `--ws-area`), whatever
   the header, the insets, the banner or the strip add up to. The same
   mechanism the project page uses in the installed layout (see "The lander
   fills what is left of the scroller"), for the same reason: nothing here
   depends on a header height being accurate.

   `flex-shrink: 0` on every link, never `min-height: 0`. On a window too
   short for the 360px floor the column must stay its content's height and
   make the screen scroll: a link allowed to shrink leaves the feed
   overflowing it, and a scroller's block-end padding follows its in-flow
   children, not a descendant that overflows one, so the clearance would
   reserve nothing (#3053 is the same trap on a project page).

   `:not(.hidden)` on the root is load-bearing. The needs pane stays mounted
   while you are on another screen, and an id-specific `display` here would
   otherwise outrank Tailwind's `.hidden` and draw Communities over it.
   `width: 100%` on the column because auto margins on a flex column's cross
   axis shrink an item to its content (`#dev-workshop` above has the same
   note); `max-w-2xl mx-auto` still caps and centres it. Its `pb-8` gives way
   to `--ws-gap`, which is the air this line has always had above the bar.

   Below 768px only: from there the bar is a rail down the side, nothing is
   parked at the foot (the strip gives way to Recents), and the rule below
   keeps the desktop's own line. */
@media (max-width: 767.98px) {
  #workshop-screen:not(.hidden):has(> div > [data-workshop-pane="needs"]) {
    display: flex; flex-direction: column;
  }
  #workshop-screen > div:has(> [data-workshop-pane="needs"]) {
    flex: 1 0 auto; width: 100%;
    display: flex; flex-direction: column;
    padding-bottom: var(--ws-gap);
  }
  #workshop-screen [data-workshop-pane="needs"] {
    flex: 1 0 auto;
    display: flex; flex-direction: column;
  }
  #workshop-screen [data-workshop-pane="needs"] > .workshop-needs-feed { flex: 1 0 0px; }
}
@media (min-width: 768px) {
  /* No tab bar: the stage runs to 8px off the floor, as a project's does, so
     the rail and its arrows clear the key legend under it. */
  .workshop-needs-feed { height: calc(100dvh - 124px - var(--browser-banner-h, 0px)); }
  /* The key legend is centred under the STAGE, not under the stage and the
     rail: this screen's column is narrower than a project's panel, so the
     legend is wider than the stage and, centred on both, ran under the
     rail's arrows. 102px is the rail and its gap. */
  .workshop-needs-feed .dev-ws-keys { inset-inline-end: 102px; }
}

/* ── The AI tab's main view (#6019 follow-up, features/ai/) ──────────────
   A page like Communities: the list on the wallpaper (the screen lists in
   this file name #ai-screen beside #workshop-screen). Its Ask Homeroom bot
   bar sits over the tab bar like a composer, on a phone; from 768px (1 Nov
   2026; it was 1024px) the column docks beside the list instead
   (data-ai-docked), with Main, the chat with the bot, or one thread of it. */
#ai-screen .ai-askbar {
  position: fixed;
  /* Where the page's own content is (the rail and its gutter, mirrored on
     the far edge), so on a wide window whose Main is not docked (yet, or at
     all) the bar is the page's and never runs under the sidebar. Both are 0
     on a phone. */
  inset-inline-start: calc(var(--platform-rail-w, 0px) + var(--platform-gutter, 0px));
  inset-inline-end: var(--platform-gutter, 0px);
  bottom: var(--platform-tabs-h, 56px);
  z-index: 25;
  padding: 6px 12px 8px;
}
#ai-screen .ai-askbar-card {
  display: flex;
  align-items: center;
  gap: 6px;
  width: 100%;
  text-align: start;
}
/* THE BAR LIFTS OFF THE WHITE LIST (asked 21 Nov 2026): on a phone the Ask
   Homeroom bot bar is a white pill over a mostly white list, so its thin
   outline alone let it disappear. It keeps that outline (the first layer, the
   Standard look's inset hairline) and takes the raised surfaces' own soft
   shadow under it, in the app's colours. Spread all round rather than only
   downward, because the bar sits right on the tab bar. The frame looks draw
   this bar their own way and are left alone; the brand look wears the same
   bar as the standard page. */
html #ai-screen .ai-askbar-card {
  box-shadow: var(--messages-disc-shadow),
    0 2px 6px var(--app-sheet-shadow-near),
    0 8px 24px -4px var(--app-sheet-shadow-far);
}
html #ai-screen .ai-askbar-card:focus-within {
  box-shadow: var(--messages-disc-shadow), 0 0 0 2px var(--accent),
    0 2px 6px var(--app-sheet-shadow-near),
    0 8px 24px -4px var(--app-sheet-shadow-far);
}
#ai-screen .ai-askbar-text {
  flex: 1;
  min-width: 0;
  font-size: 17px;
  line-height: 22px;
  padding: 9px 4px;
  color: var(--text-faint);
}
#ai-screen .ai-askbar-gap { height: 76px; }
#ai-screen[data-ai-docked] .ai-askbar,
#ai-screen[data-ai-docked] .ai-askbar-gap { display: none; }
/* Main's column is the side panel's width (features/side-panel/), so a page
   opened from the list takes its place without the list moving. Held inside
   the window here as well: that width is the one chosen beside an app, kept
   per device and put on <html> at boot, so a width picked on a wide monitor
   would otherwise run Main under the rail and over the list on a narrower
   window. The list keeps the 480px an app keeps beside the panel. Set on
   <body> while the page is up, so the panel (a sibling of the page, not in
   it) takes the same width in Main's place.
   UNTIL A WIDTH IS CHOSEN (30 Oct 2026), Main takes the room the list does
   not need. Since 3 Nov 2026 that is ALL of it, with no 720px upper limit:
   Main is the rest of the window, and only the list's own margins separate
   them. With the old cap at 720px a 1720px window left a band of empty
   background between the two and a narrow, tall column for plan cards. The
   400px floor stays. THE LIST GIVES WHAT IT TAKES (#6495, 9 Nov 2026): while
   something is open beside it the list is the inbox's own measure
   (`--list-pane-w`), so the two list-and-open pages share one layout; with
   nothing open it stays the centred 672px single column (`max-w-2xl`,
   features/ai/index.tsx), as Home and Needs you are.
   A width dragged on Main's edge is Main's own (`--ai-main-chosen-w` and its
   own device key, features/side-panel/resize.ts), so a width chosen for the
   side panel beside an app no longer sizes Main, and the reverse.
   THE ROOM IS BESIDE THE DUO'S COLUMN (1 Nov 2026). `--ai-room` is the
   window less the rail and iPhone Duo's column of system chrome
   (`--platform-strip-w`, THE SIDE STRIP; 0 everywhere else). Unfolded and
   held sideways the Duo is 951px with an 84px column the body pads out, so
   sums taken from 100vw counted the column twice: Main came out 379px and
   the list's card 220px. Since the same day the room is the page's usable
   box (`--platform-usable-w`, THE USABLE BOX beside the rail's tokens),
   which takes the rail and the column off once for every reader: the same
   value, decided in one place.
   THE PINNED COLUMNS RUN UNDER IT (1 Nov 2026), as the header does: Main,
   the side panel in its place and a design's preview reach the screen's
   edge. Stopped at the column instead, Main ended in a hard edge with bare
   wallpaper beside it. The clock, the camera and the Wi-Fi ring sit at the
   column's top, within the height of each column's head, so the heads pad
   their contents by the column (`--ai-edge`). Below that the column is
   plain screen (taps reach the page there, measured on the Duo simulator),
   so Main's chat and the page in the side panel run under it: padded too,
   they left a band of the column's own colour beside a chat that stopped
   short. A design's preview pads the column, as its ✕ is at its top. */
body:has(#ai-screen:not(.hidden)) {
  --ai-room: var(--platform-usable-w);
  --ai-list-min: var(--list-pane-w);
  --ai-main-auto: max(400px, calc(var(--ai-room) - var(--list-pane-w)));
  --ai-main-w: max(var(--ai-main-floor, 320px), min(var(--ai-main-chosen-w, var(--ai-main-auto)), calc(var(--ai-room) - var(--ai-list-min))));
}
/* THE THREAD TAKES THE SPARE ROOM (24 Nov 2026). The list beside an open
   column is held to 42rem (`--ai-list-max`, the body rule below), and the
   column used to be held to nothing but 320px: dragged narrower than the
   room less 42rem, it left the list's side wider than the list, and the
   list floated between two empty bands (about 135px each with the sidebar
   folded at 1720px and the column at 715px). Now the column is never
   narrower than the room less the list's 42rem, so the list's 16px card
   margins are the only space beside it. A width stored narrower is raised
   to it when applied and kept as stored, so a window that narrows again
   gives it back; the divider stops there too, reading the same 42rem
   (features/side-panel/resize.ts probeLayout). The thread's own 320px,
   the list's floor and the snap that hides it are as they were. Declared
   only beside the lists: a preview's columns (`[data-ai-preview]`) keep
   their own widths, which read `--ai-main-w` as it was, and the frame's
   looks lay the list out at a width of their own. A phone has no columns. */
@media (min-width: 768px) {
  body:has(#ai-screen:not(.hidden):not([data-ai-preview])) {
    --ai-list-max: 42rem;
    --ai-main-floor: max(320px, calc(var(--ai-room) - var(--ai-list-max)));
  }
}
html[data-side-strip="right"] body:has(#ai-screen:not(.hidden)) {
  --ai-edge: var(--platform-strip-w, 0px);
}
/* A NOTCH ON THE RIGHT (an iPhone held sideways, THE NOTCH below) is an
   edge the same way, for the columns' width and their heads. Unlike the
   Duo's column it is the camera island halfway down, not plain screen, so
   Main's chat and the page in its place keep clear of it too. */
html:not([data-side-strip]):not([data-side-corner]) body:has(#ai-screen:not(.hidden)) {
  --ai-edge: var(--platform-notch-right, 0px);
}
/* Main stands on the left in Arabic, so the edge beside it is that side's. */
