.dev-kanban-foot { margin: 2px 0 2px; }
.dev-kanban-foot > .dev-kanban-more { justify-content: flex-start; padding: 8px 2px; font-size: 13px; }
.dev-kanban-card > .dev-col-divider { margin: 10px 2px 2px; }

/* ── By stage, the board sits on the page ────────────────────────────
   The columns are the cards, so the pane around them draws no sheet of its
   own, and its head is on the page until it pins: then the row and the
   steps take the sheet's colour, square on top under the tabs and rounded
   below, with a hairline at their foot (`data-ws-head-pinned`). */
#dev-workshop.dev-ws-has-board .dev-ws-pane { box-shadow: none; }
#dev-workshop.dev-ws-has-board .dev-ws-pane-head,
#dev-workshop.dev-ws-has-board .dev-ws-pane-body { background-color: transparent; backdrop-filter: none; -webkit-backdrop-filter: none; }
#dev-workshop.dev-ws-has-board .dev-ws-pane-head { gap: 12px; padding: 8px 10px 10px; }
#dev-workshop.dev-ws-has-board .dev-ws[data-ws-head-pinned] .dev-ws-pane-head {
  background-color: var(--dc-sheet-solid);
  border-start-start-radius: 0; border-start-end-radius: 0; border-end-end-radius: 18px; border-end-start-radius: 18px;
  box-shadow: inset 0 -1px 0 var(--app-sheet-line);
}

/* ── The board beside the panel (#4486) ──────────────────────────────
   A row opens its page in the Workshop's panel; the board keeps its place
   to its left, its columns 316px, and scrolls sideways (the Workshop brings
   the tapped column beside the panel). */
#dev-workshop.dev-ws-has-board:has(> .dev-ws[data-ws-side-open]) { margin-inline-start: 24px; max-width: var(--dev-ws-side-list-w); }
.dev-ws[data-ws-side-open] :is(#dev-kanban, .dev-kanban-stages) { grid-template-columns: repeat(4, 316px); }

@media (max-width: 639px) {
  /* #4486: on a phone the steps are the tabs, one column at a time, and
     they scroll sideways on their own. */
  .dev-kanban-stages {
    display: flex; gap: 6px; padding: 0 0 2px; margin-top: 2px;
    overflow-x: auto; scrollbar-width: none;
  }
  .dev-kanban-stages::-webkit-scrollbar { display: none; }
  .dev-kanban-step {
    flex: none; min-height: 40px; padding-block: 6px 6px; padding-inline: 7px 13px; gap: 7px; cursor: pointer;
    border-radius: 999px; background: var(--state-neutral-bg);
  }
  /* Request 7029: a tab is drawn 40px tall and pressed at 44. The strip
     clips what is past it, so its 2px of room above is padding here, not
     margin, and the tab's hit box reaches 2px into it and into the 2px below. */
  .dev-kanban-stages { margin-top: 0; padding-block: 2px; }
  .dev-kanban-step::after { content: ""; position: absolute; inset: -2px 0; }
  .dev-kanban-step[aria-selected="true"] { background: var(--lit-tint); box-shadow: inset 0 0 0 1px var(--lit-line); }
  .dev-kanban-step[aria-selected="true"] :is(.dev-kanban-step-name, .dev-kanban-step-tile) { color: var(--lit-ink); }
  .dev-kanban-step-tile, .dev-kanban-step-tile[data-kind="done"] { width: 22px; height: 22px; border-radius: 999px; background: transparent; }
  .dev-kanban-step-name, .dev-kanban-step-n { font-size: 14px; }
  .dev-kanban-step-arrow { display: none; }
  .dev-kanban-card { padding: 2px 12px 6px; }
  /* The head: the way back and the name, then the search on its own line,
     and the switch and the filters sharing the line under it (#5029). */
  .dev-ws-allbar #dev-kanban-search { flex-basis: 100%; max-width: none; min-width: 0; }
  /* #5820: the grouping stays at the left and the filters at the right edge,
     so the line reads as two groups. It still scrolls when it overflows. */
  .dev-ws-allbar #dev-filter-chips { flex: 0 1 auto; margin-inline-start: auto; min-width: 0; flex-wrap: nowrap; overflow-x: auto; scrollbar-width: none; }
  /* Request 7029: the row's scrollbar is put away in every browser (it
     fades at the end that has more, kanban-filters.tsx), and a chip, drawn
     28 to 36px tall, is pressed at 44: the row keeps room above and below
     its chips for that, pulled back so the head is no taller. */
  .dev-ws-allbar #dev-filter-chips::-webkit-scrollbar { display: none; }
  .dev-ws-allbar #dev-filter-chips { padding-block: 8px; margin-block: -8px; }
  .dev-ws-allbar #dev-filter-chips button { position: relative; flex: none; }
  .dev-ws-allbar #dev-filter-chips button::after { content: ""; position: absolute; inset-inline: 0; top: 50%; height: 44px; transform: translateY(-50%); }
  .dev-ws-allbar .dev-ws-pagehead-title { font-size: 20px; line-height: 26px; }
}
/* Where the board is one column (the container query above) the steps are
   the tabs, as on a phone (#77). */
@container ws-board (max-width: 975.98px) {
  .dev-ws:not([data-ws-side-open]) .dev-kanban-stages {
    display: flex; gap: 6px; padding: 0 0 2px; margin-top: 2px;
    overflow-x: auto; scrollbar-width: none;
  }
  .dev-ws:not([data-ws-side-open]) .dev-kanban-stages::-webkit-scrollbar { display: none; }
  .dev-ws:not([data-ws-side-open]) .dev-kanban-step {
    flex: none; min-height: 40px; padding-block: 6px 6px; padding-inline: 7px 13px; gap: 7px; cursor: pointer;
    border-radius: 999px; background: var(--state-neutral-bg);
  }
  /* Request 7029: pressed at 44px, as on a phone (above). */
  .dev-ws:not([data-ws-side-open]) .dev-kanban-stages { margin-top: 0; padding-block: 2px; }
  .dev-ws:not([data-ws-side-open]) .dev-kanban-step::after { content: ""; position: absolute; inset: -2px 0; }
  .dev-ws:not([data-ws-side-open]) .dev-kanban-step[aria-selected="true"] { background: var(--lit-tint); box-shadow: inset 0 0 0 1px var(--lit-line); }
  .dev-ws:not([data-ws-side-open]) .dev-kanban-step[aria-selected="true"] :is(.dev-kanban-step-name, .dev-kanban-step-tile) { color: var(--lit-ink); }
  .dev-ws:not([data-ws-side-open]) :is(.dev-kanban-step-tile, .dev-kanban-step-tile[data-kind="done"]) { width: 22px; height: 22px; border-radius: 999px; background: transparent; }
  .dev-ws:not([data-ws-side-open]) :is(.dev-kanban-step-name, .dev-kanban-step-n) { font-size: 14px; }
  .dev-ws:not([data-ws-side-open]) .dev-kanban-step-arrow { display: none; }
