}
html:root #messages-screen .messages-layout > :is(.messages-thread-pane:not(.messages-no-selection), .messages-reply-pane)::before {
  content: '';
  grid-row: 3 / 8;
  grid-column: 1;
  z-index: -1;
  border-radius: 20px;
  background: var(--one-surface);
  box-shadow: inset 0 0 0 1px var(--one-hair);
}
html:root #messages-screen .messages-layout > :is(.messages-thread-pane:not(.messages-no-selection), .messages-reply-pane) > :not(.messages-reply-resizer, .messages-drop-overlay) { grid-column: 1; min-width: 0; }
html:root #messages-screen .messages-layout > :is(.messages-thread-pane:not(.messages-no-selection), .messages-reply-pane) > .messages-thread-header { grid-row: 1; }
html:root #messages-screen .messages-layout > :is(.messages-thread-pane:not(.messages-no-selection), .messages-reply-pane) > .messages-invitation { grid-row: 2; margin: 0 0 10px; }
html:root #messages-screen .messages-layout > :is(.messages-thread-pane:not(.messages-no-selection), .messages-reply-pane) > [data-transcript-overlay="top"] { grid-row: 3; }
html:root #messages-screen .messages-layout > :is(.messages-thread-pane:not(.messages-no-selection), .messages-reply-pane) > .messages-thread-scroll { grid-row: 4; }
html:root #messages-screen .messages-layout > :is(.messages-thread-pane:not(.messages-no-selection), .messages-reply-pane) > [data-transcript-overlay="foot"] { grid-row: 5; }
html:root #messages-screen .messages-layout > :is(.messages-thread-pane:not(.messages-no-selection), .messages-reply-pane) > .chat-status { grid-row: 6; }
html:root #messages-screen .messages-layout > :is(.messages-thread-pane:not(.messages-no-selection), .messages-reply-pane) > :is(.messages-composer, .messages-composer-disabled) { grid-row: 7; }

/* The title card: who it is with, "Direct message" (or the group's members) over the name, and the discs. */
html:root #messages-screen .messages-layout > :is(.messages-thread-pane:not(.messages-no-selection), .messages-reply-pane) > .messages-thread-header {
