html:root #messages-screen .messages-thread-header > .messages-group-faces { border-radius: 0; }
html:root #messages-screen .messages-thread-header > .messages-group-faces > :first-child { inset: 0; width: 40px; height: 40px; border-radius: 9999px; font-size: 16px; }
html:root #messages-screen .messages-thread-header > .messages-group-faces > :last-child:not(:first-child) {
