/* The name block: the line over the name (the markup keeps the name first, the declared checks read it so). */
html:root #messages-screen .messages-thread-header > button.flex-1 { display: flex; flex-direction: column; gap: 2px; }
html:root #messages-screen .messages-thread-header .messages-thread-sub { order: -1; color: var(--one-ink-2); font-size: 14px; font-weight: 400; line-height: 18px; }
