html:root #messages-screen .messages-layout > :is(.messages-thread-pane:not(.messages-no-selection), .messages-reply-pane) > .chat-status { padding-inline: 16px; }
/* The message bar, inside the card at its foot. */
html:root #messages-screen .messages-layout > :is(.messages-thread-pane:not(.messages-no-selection), .messages-reply-pane) > .messages-composer {
