  box-shadow: inset 0 0 0 1px rgb(18 26 14 / 0.16);
}
html:root :is(#messages-screen .messages-thread-pane, #messages-screen .messages-reply-pane, #dev-topic-thread .dev-request-sheet) .messages-composer-card .messages-send svg { width: 19px; height: 19px; stroke-width: 2.2; }
html:root :is(#messages-screen .messages-thread-pane, #messages-screen .messages-reply-pane, #dev-topic-thread .dev-request-sheet) .messages-composer-card .messages-send:disabled,
html:root :is(#messages-screen .messages-thread-pane, #messages-screen .messages-reply-pane, #dev-topic-thread .dev-request-sheet) .messages-composer-card:not([data-gc-files]):has(textarea:placeholder-shown) .messages-send:not([data-bot-stop]) {
