html.dark:root :is(#messages-screen .messages-thread-pane, #messages-screen .messages-reply-pane, #dev-topic-thread .dev-request-sheet) .messages-composer-card .messages-send:disabled,
html.dark:root :is(#messages-screen .messages-thread-pane, #messages-screen .messages-reply-pane, #dev-topic-thread .dev-request-sheet) .messages-composer-card:not([data-gc-files]):has(textarea:placeholder-shown) .messages-send:not([data-bot-stop]) {
