html:root .messages-message.messages-message-bubble > :is(span[aria-hidden], img):first-child {
  flex: 0 0 32px;
  width: 32px;
  height: 32px;
  border-radius: 9999px;
  font-size: 14px;
}
html:root .messages-message.messages-message-bubble > .messages-message-gutter { flex: 0 0 44px; width: 44px; }
