html:root .messages-message.messages-message-bubble:not(.messages-message-self) .messages-bubble,
html:root .messages-message.messages-message-bubble.messages-message-self .messages-bubble {
  max-width: 88%;
  padding: 8px 12px;
  border-radius: 16px;
  border-start-start-radius: 4px;
  background: var(--one-bubble-in);
  color: var(--one-ink);
  font-size: 1rem;
  line-height: 1.375rem;
}
html:root .messages-message.messages-message-bubble.messages-message-self .messages-bubble {
  max-width: 82%;
  border-radius: 16px;
  border-start-end-radius: 4px;
  background: var(--one-bubble-out);
}
/* The same person again: the bubble keeps all four corners round. */
html:root .messages-message.messages-message-bubble.messages-message-grouped .messages-bubble { border-radius: 16px; }
html:root .messages-message.messages-message-bubble .messages-bubble .messages-markdown.gc-msg-content { color: inherit; font-size: inherit; line-height: inherit; }
html:root .messages-message.messages-message-bubble .messages-bubble.messages-bubble-rich { max-width: min(100%, 720px); }
